    // Build IDs for a
    for (int a = 1; a <= maxx; ++a) {
        int g = std::gcd(a, rev[a]);
        int p = a / g;
        int q = rev[a] / g;
        idA[a] = get_id(p, q);
    }
    // Build IDs for b
    for (int b = 1; b <= maxy; ++b) {
        int g = std::gcd(b, rev[b]);
        int p = rev[b] / g;
        int q = b / g;
        idB[b] = get_id(p, q);
