            int s_min_from_others = INT_MAX;
            // min over other children excluding 'to'
            int otherMinChild = INT_MAX;
            // Use precomputed min1/min2: if this child is the one with min1, use min2; else use min1
            if(to == idxMin1Child) otherMinChild = min2Child; else otherMinChild = min1Child;
            s_min_from_others = min(parentComp, otherMinChild);
            int L = M - half;
            int R = half - s_min_from_others;
            int yl = max(1, L);
            int yr = R;
            if(yl <= yr){
