            }
        }
        // Handle parent candidate if parent side size equals M
        if(parentComp == M && v != 1){
            int s_min = minChildAll; // min sz among children
            if(minChildAll == INT_MAX) s_min = INT_MAX; // no children
            int L = M - half;
            int R = half - s_min;
            int yl = max(1, L);
            int yr = R;
            if(yl <= yr){
                // two x-ranges: [1, tin[v]-1] and [tout[v]+1, n]
                int leftL = 1, leftR = tin[v]-1;
                if(leftL <= leftR) queries.push_back({leftL, leftR, yl, yr, v});
                int rightL = tout[v]+1, rightR = n;
                if(rightL <= rightR) queries.push_back({rightL, rightR, yl, yr, v});
            }
        }
    }

    // Answer queries using the 2D segment tree; if any query for v succeeds, ans[v] = 1
    for(const auto &q : queries){
        if(ans[q.v] == 1) continue; // already possible, skip
        if(q.xl > q.xr || q.yl > q.yr) continue;
        if(querySeg(1, 1, n, q.xl, q.xr, q.yl, q.yr)){
            ans[q.v] = 1;
        }
    }

    // Output
    for(int i=1;i<=n;i++){
        cout << ans[i] << (i==n ? '\n' : ' ');
    }
    return 0;
}
