            print("Test failed.")
            sys.exit(1)
        cost_prog = int(out)
        cost_brute = brute_cost(a, b)
        if cost_prog != cost_brute:
            print("Mismatch!")
            print("Input:\n" + input_str)
            print("Program:", cost_prog, "Brute:", cost_brute)
            sys.exit(2)
    print("All tests passed")

if __name__ == "__main__":
    main()
