#include <bits/stdc++.h>
using namespace std;

struct Block {
  int start, end; // inclusive indices in the original array
  vector<int> raw; // actual values stored (excluding tag)
  int tag; // lazy additive tag applied to all elements in the block
  unordered_map<int,int> freq; // frequency of values in raw
  int min_raw, max_raw; // min/max of raw values
  Block() {}
  Block(int s, int e, const vector<int>& base) {
    start = s; end = e; tag = 0;
    raw.assign(base.begin()+s, base.begin()+e+1);
    rebuild();
  }
  void rebuild() {
    freq.clear(); min_raw = INT_MAX; max_raw = INT_MIN;
    for (int v : raw) {
      freq[v]++;
      if (v < min_raw) min_raw = v;
      if (v > max_raw) max_raw = v;
    }
    if (raw.empty()) { min_raw = INT_MAX; max_raw = INT_MIN; }
  }
  void push_tag() {
    if (tag != 0) {
      for (int i = 0; i < (int)raw.size(); ++i) raw[i] += tag;
      tag = 0;
      rebuild();
    }
  }
  int count_full(int x) {
    int need = x - tag; // value in raw that equals (x - tag)
    auto it = freq.find(need);
    return (it == freq.end()) ? 0 : it->second;
  }
  void update_partial(int lpos, int rpos, int x) {
    for (int p = lpos; p <= rpos; ++p) {
      int old_raw = raw[p];
      long long actual = (long long)old_raw + tag;
      if (actual > x) {
        int new_raw = old_raw - x;
        auto it = freq.find(old_raw);
        if (it != freq.end()) {
          if (--(it->second) == 0) freq.erase(it);
        }
        raw[p] = new_raw;
        freq[new_raw]++;
      }
    }
    min_raw = INT_MAX; max_raw = INT_MIN;
    for (int v : raw) { if (v < min_raw) min_raw = v; if (v > max_raw) max_raw = v; }
  }
  int get_actual_min() const { return min_raw + tag; }
  int get_actual_max() const { return max_raw + tag; }
  int startIdx() const { return start; }
  int endIdx() const { return end; }
  void update_full_subtract_with_push(int x) {
    push_tag();
    for (int i = 0; i < (int)raw.size(); ++i) if (raw[i] > x) raw[i] -= x;
    rebuild();
  }
  void subtract_entire_block_tag_only(int x) {
    tag -= x;
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int n, m;
  if (!(cin >> n >> m)) return 0;
  vector<int> a(n);
  for (int i = 0; i < n; ++i) cin >> a[i];

  int B = 700; // block size
  vector<Block> blocks;
  vector<int> block_of(n);
  for (int i = 0; i < n; i += B) {
    int l = i;
    int r = min(n - 1, i + B - 1);
    blocks.emplace_back(l, r, a);
    int bid = (int)blocks.size() - 1;
    for (int j = l; j <= r; ++j) block_of[j] = bid;
  }

  while (m--) {
    int t, l, r, x;
    cin >> t >> l >> r >> x;
    int L = l - 1, R = r - 1;
    if (t == 1) {
      int bl = block_of[L];
      int br = block_of[R];
      if (bl == br) {
        Block &blk = blocks[bl];
        int lpos = L - blk.startIdx();
        int rpos = R - blk.startIdx();
        blk.update_partial(lpos, rpos, x);
      } else {
        // left partial block
        Block &left = blocks[bl];
        int lpos = L - left.startIdx();
        int rpos = left.endIdx() - left.startIdx();
        left.update_partial(lpos, rpos, x);
        // full middle blocks
        for (int b = bl + 1; b <= br - 1; ++b) {
          Block &blk = blocks[b];
          if (blk.get_actual_min() > x) blk.subtract_entire_block_tag_only(x);
          else if (blk.get_actual_max() <= x) { /* nothing */ }
          else blk.update_full_subtract_with_push(x);
        }
        // right partial block
        Block &right = blocks[br];
        int lp = 0;
        int rp = R - right.startIdx();
        right.update_partial(lp, rp, x);
      }
    } else {
      long long ans = 0;
      int bl = block_of[L];
      int br = block_of[R];
      if (bl == br) {
        Block &blk = blocks[bl];
        for (int i = L; i <= R; ++i) {
          int pos = i - blk.startIdx();
          int val = blk.raw[pos] + blk.tag;
          if (val == x) ++ans;
        }
      } else {
        // left partial
        Block &left = blocks[bl];
        for (int i = L; i <= left.endIdx(); ++i) {
          int pos = i - left.startIdx();
          int val = left.raw[pos] + left.tag;
          if (val == x) ++ans;
        }
        // full middle blocks
        for (int b = bl + 1; b <= br - 1; ++b) ans += blocks[b].count_full(x);
        // right partial
        Block &right = blocks[br];
        for (int i = right.startIdx(); i <= R; ++i) {
          int pos = i - right.startIdx();
          int val = right.raw[pos] + right.tag;
          if (val == x) ++ans;
        }
      }
      cout << ans << "\n";
    }
  }
  return 0;
}
