  int min_raw, max_raw; // min/max of raw values
  Block() {}
  Block(int s, int e, const vector<int>& base) {
    start = s; end = e; tag = 0;
    raw.assign(base.begin()+s, base.begin()+e+1);
    rebuild();
  }
  void rebuild() {
    freq.clear(); min_raw = INT_MAX; max_raw = INT_MIN;
    for (int v : raw) {
      freq[v]++;
      if (v < min_raw) min_raw = v;
      if (v > max_raw) max_raw = v;
    }
    if (raw.empty()) { min_raw = INT_MAX; max_raw = INT_MIN; }
  }
  void push_tag() {
