#include <bits/stdc++.h>
using namespace std;

struct Rook { int x, y; };
struct Query { int x1, y1, x2, y2, id; };

// Simple iterative segment tree for range minimum with 1-based indices
struct SegMin {
    int n, S;
    vector<int> t;
    SegMin(int n = 0) { init(n); }
    void init(int n_) {
        n = n_;
        S = 1;
        while (S < n) S <<= 1;
        t.assign(2*S, 0); // initial values are 0 (no rook seen yet)
    }
    void update(int pos, int val) {
        int p = pos - 1 + S;
        t[p] = val; // since we sweep in increasing order, this is effectively max so far
        for (p >>= 1; p; p >>= 1) t[p] = min(t[p<<1], t[p<<1|1]);
    }
    int query(int l, int r) {
        if (l > r) return INT_MAX;
        int res = INT_MAX;
        int L = l - 1 + S, R = r - 1 + S;
        while (L <= R) {
            if (L & 1) res = min(res, t[L++]);
            if (!(R & 1)) res = min(res, t[R--]);
            L >>= 1; R >>= 1;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, q;
    if (!(cin >> n >> m >> k >> q)) return 0;

    vector<Rook> rooks(k);
    for (int i = 0; i < k; ++i) cin >> rooks[i].x >> rooks[i].y;

    vector<Query> queries(q);
    for (int i = 0; i < q; ++i) {
        cin >> queries[i].x1 >> queries[i].y1 >> queries[i].x2 >> queries[i].y2;
        queries[i].id = i;
    }

    // Sweep 1: rows condition (all rows in [x1,x2] have a rook with y in [y1,y2])
    vector<Rook> rooks_by_y = rooks;
    sort(rooks_by_y.begin(), rooks_by_y.end(), [](const Rook &a, const Rook &b){ return a.y < b.y; });
    vector<Query> by_y2 = queries;
    sort(by_y2.begin(), by_y2.end(), [](const Query &a, const Query &b){ return a.y2 < b.y2; });

    SegMin segRow(n);
    vector<char> okRow(q, 0);
    int idx = 0;
    for (auto &qq : by_y2) {
        while (idx < (int)rooks_by_y.size() && rooks_by_y[idx].y <= qq.y2) {
            segRow.update(rooks_by_y[idx].x, rooks_by_y[idx].y);
            ++idx;
        }
        int minv = segRow.query(qq.x1, qq.x2);
        if (minv >= qq.y1) okRow[qq.id] = 1;
    }

    // Sweep 2: columns condition (all columns in [y1,y2] have a rook with x in [x1,x2])
    vector<Rook> rooks_by_x = rooks;
    sort(rooks_by_x.begin(), rooks_by_x.end(), [](const Rook &a, const Rook &b){ return a.x < b.x; });
    vector<Query> by_x2 = queries;
    sort(by_x2.begin(), by_x2.end(), [](const Query &a, const Query &b){ return a.x2 < b.x2; });

    SegMin segCol(m);
    vector<char> okCol(q, 0);
    idx = 0;
    for (auto &qq : by_x2) {
        while (idx < (int)rooks_by_x.size() && rooks_by_x[idx].x <= qq.x2) {
            segCol.update(rooks_by_x[idx].y, rooks_by_x[idx].x);
            ++idx;
        }
        int minv = segCol.query(qq.y1, qq.y2);
        if (minv >= qq.x1) okCol[qq.id] = 1;
    }

    // Output results
    for (int i = 0; i < q; ++i) {
        cout << ((okRow[i] || okCol[i]) ? "YES" : "NO") << '\n';
    }

    return 0;
}
