    cin.tie(nullptr);

    int N, Q; if(!(cin >> N >> Q)) return 0;
    vector<vector<pair<int,int>>> adj(N+1);
    for(int i = 0; i < N-1; ++i){
        int u,v,w; cin >> u >> v >> w;
        adj[u].push_back({v,w});
        adj[v].push_back({u,w});
    }

    int LOG = 1; while((1<<LOG) <= N) ++LOG;
    vector<int> depth(N+1,0);
    vector<long long> distRoot(N+1,0);
    vector<int> parent(N+1,0);
    vector<int> wpar(N+1,0);

    // Iterative DFS to fill parent, depth, distRoot, wpar
    vector<int> st; st.reserve(N); st.push_back(1);
    parent[1] = 0; depth[1] = 0; distRoot[1] = 0; wpar[1] = 0;
    while(!st.empty()){
        int u = st.back(); st.pop_back();
        for(auto &e : adj[u]){
            int v = e.first; int w = e.second; if(v == parent[u]) continue;
            parent[v] = u; depth[v] = depth[u] + 1; distRoot[v] = distRoot[u] + w; wpar[v] = w;
            st.push_back(v);
        }
    }

    vector<vector<int>> up(LOG, vector<int>(N+1, 0));
    vector<vector<long long>> distUp(LOG, vector<long long>(N+1, 0)); // distance to up[k][v]
    for(int v=1; v<=N; ++v){ up[0][v] = parent[v]; distUp[0][v] = wpar[v]; }
    for(int k=1; k<LOG; ++k){
        for(int v=1; v<=N; ++v){ int mid = up[k-1][v]; up[k][v] = mid ? up[k-1][mid] : 0; if(mid) distUp[k][v] = distUp[k-1][v] + distUp[k-1][mid]; else distUp[k][v] = distUp[k-1][v]; }
    }

    auto LCA = [&](int a, int b){
        if(depth[a] < depth[b]) swap(a,b);
        int diff = depth[a] - depth[b];
        for(int k=0; k<LOG; ++k) if((diff>>k)&1) a = up[k][a];
        if(a == b) return a;
        for(int k=LOG-1; k>=0; --k){ if(up[k][a] != up[k][b]){ a = up[k][a]; b = up[k][b]; } }
        return up[0][a];
    };

    auto dist = [&](int a, int b){ int c = LCA(a,b); return distRoot[a] + distRoot[b] - 2*distRoot[c]; };

    auto go_up_by_dist = [&](int v, long long d){
        if(d < 0) return -1;
        for(int k=LOG-1; k>=0; --k){
            if(up[k][v] != 0 && distUp[k][v] <= d){
                d -= distUp[k][v];
                v = up[k][v];
            }
        }
        if(d == 0) return v;
        return -1; // cannot land exactly on a vertex
    };

    auto kth_on_path = [&](int p, int q, long long k)->int{
        int L = LCA(p,q);
        long long d_pL = distRoot[p] - distRoot[L];
        long long d_qL = distRoot[q] - distRoot[L];
        long long total = d_pL + d_qL;
        if(k < 0 || k > total) return -1;
        if(k <= d_pL) return go_up_by_dist(p, k);
        long long rem = k - d_pL;
        if(rem > d_qL) return -1;
        long long dist_from_q = d_qL - rem; // distance from q to target along path q->L
        return go_up_by_dist(q, dist_from_q);
    };

    while(Q--){
        int a,b,c; cin >> a >> b >> c;
        long long dab = dist(a,b), dbc = dist(b,c), dca = dist(c,a);
        int p=a,q=b,r=c;
        if(dbc >= dab && dbc >= dca){ p=b; q=c; r=a; }
        else if(dab >= dbc && dab >= dca){ p=a; q=b; r=c; }
        else { p=c; q=a; r=b; }
        long long c_len = dist(p,q);
        long long d_pr = dist(r,p);
        long long d_qr = dist(r,q);

        vector<int> cand;
        cand.push_back(p);
        cand.push_back(q);
        // middle vertex on path p-q (if exists)
        if(c_len >= 0){
            if(c_len % 2 == 0){ int node = kth_on_path(p,q, c_len/2); if(node != -1) cand.push_back(node); }
            else { int n1 = kth_on_path(p,q, c_len/2); if(n1 != -1) cand.push_back(n1); int n2 = kth_on_path(p,q, c_len/2 + 1); if(n2 != -1) cand.push_back(n2); }
        }
        // projection of r onto path p-q
        long long tnum = d_pr - d_qr + c_len; // t = (dist(r,p) - dist(r,q) + dist(p,q)) / 2
        if((tnum & 1LL) == 0){ long long t = tnum / 2; if(t >= 0 && t <= c_len){ int m = kth_on_path(p,q, t); if(m != -1) cand.push_back(m); } }

        sort(cand.begin(), cand.end()); cand.erase(unique(cand.begin(), cand.end()), cand.end());
        long long ans = LLONG_MAX;
        for(int x : cand){ long long cur = max({ dist(x,a), dist(x,b), dist(x,c) }); if(cur < ans) ans = cur; }
        cout << ans << "\n";
    }

    return 0;
}
