  if(!(cin >> n >> q)) return 0;

  vector<vector<int>> g(n+1);
  for(int i = 2; i <= n; ++i){
    int par; cin >> par;
    g[par].push_back(i);
  }

  // Iterative preorder to gather order for postorder processing
  vector<int> order; order.reserve(n);
  vector<int> st; st.push_back(1);
  while(!st.empty()){
    int v = st.back(); st.pop_back();
    order.push_back(v);
    for(int u : g[v]) st.push_back(u);
  }

  // Compute subtree sizes and heavy child
  vector<int> sz(n+1, 0), heavy(n+1, 0);
  for(int idx = (int)order.size()-1; idx >= 0; --idx){
    int v = order[idx];
    sz[v] = 1; int best = 0;
    for(int u : g[v]){
      sz[v] += sz[u];
      if(sz[u] > sz[best]) best = u;
    }
    heavy[v] = best; // 0 if leaf
  }

  const int LOG = 20; // since 2^19 > 3e5
  vector<vector<int>> up(LOG, vector<int>(n+1, 0));
  for(int v = 1; v <= n; ++v) up[0][v] = heavy[v];
  for(int k = 1; k < LOG; ++k){
    for(int v = 1; v <= n; ++v){
      int mid = up[k-1][v];
      up[k][v] = mid ? up[k-1][mid] : 0;
    }
  }

  // Compute centroid for every v
  vector<int> cent(n+1, 0);
  for(int v = 1; v <= n; ++v){
    int ssz = sz[v];
    int cur = v;
    for(int k = LOG-1; k >= 0; --k){
      int nxt = up[k][cur];
      if(nxt != 0 && sz[nxt] > ssz/2) cur = nxt;
    }
    cent[v] = cur;
  }

  // Answer queries
  for(int i = 0; i < q; ++i){
    int v; cin >> v;
    cout << cent[v] << "\n";
  }

  return 0;
}

