using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const long long MOD = 1000000007LL;
    int n;
    if(!(cin >> n)) return 0;
    vector<long long> a(n);
    long long maxVal = LLONG_MIN;
    for(int i = 0; i < n; ++i){ cin >> a[i]; if(a[i] > maxVal) maxVal = a[i]; }

