// Peterson Polyglot - full solution outline implemented with hashing and comparator-based sort.
// This program computes the minimal broom size after removing the p-th letter from all words of length >= p,
// for p in [1, maxDepth], and returns the smallest such p achieving the minimum broom size.

static const int MOD1 = 1000000007;
static const int MOD2 = 1000000009;
static const int BASE1 = 911382323;
static const int BASE2 = 972663749;

int n;
vector<vector<pair<int,char>>> adj; // 1-based, edge label as char 'a'..'z'
vector<int> depthv, parentv, ch; // ch[v] is the label index (0..25) on edge parent[v] -> v
int LOG;
vector<vector<int>> up; // up[k][v] = 2^k-th ancestor of v
vector<int> H1, H2; // path hashes to node v along root->v
vector<int> pow1, pow2; // powers for hashes
int maxDepth = 0;
int CURP = 1; // current p for comparison

int nodeAtDepth(int u, int d){ // returns node on path root->u at depth d (1-based depth). assumes d>=1 and d<=depth[u]
    int diff = depthv[u] - d;
    int v = u;
    for(int k=0; k<LOG; ++k) if(diff & (1<<k)) v = up[k][v];
    return v;
}
int kthAncestor(int u, int steps){
    for(int k=0; k<LOG; ++k) if(steps & (1<<k)) u = up[k][u];
    return u;
}

pair<int,int> prefixHash(int u, int k){
    // Returns hash of the first k letters of S(u) = path root->u with the p-th letter removed
    if(k <= 0) return {0,0};
    int d = depthv[u];
    int L = (d < CURP) ? d : d-1; // length of S(u)
    if(k > L) k = L;
    if(k <= CURP-1){ // entirely within the prefix before removed position
        int node = nodeAtDepth(u, k); // vertex at depth k
        return { H1[node], H2[node] };
    } else {
        int t = k - (CURP - 1); // number of letters taken from the suffix after removing p-th letter
        int leftNode = (CURP-1 > 0) ? nodeAtDepth(u, CURP-1) : 0;
        int left1 = (CURP-1 > 0) ? H1[leftNode] : 0;
        int left2 = (CURP-1 > 0) ? H2[leftNode] : 0;
        int node_p = nodeAtDepth(u, CURP);
        int node_pt = nodeAtDepth(u, CURP + t);
        int right1 = (H1[node_pt] - (long long) H1[node_p] * pow1[t] % MOD1 + MOD1) % MOD1;
        int right2 = (H2[node_pt] - (long long) H2[node_p] * pow2[t] % MOD2 + MOD2) % MOD2;
        int full1 = ( (long long) left1 * pow1[t] + right1 ) % MOD1;
        int full2 = ( (long long) left2 * pow2[t] + right2 ) % MOD2;
        return {full1, full2};
    }
}

int getCharAt(int u, int pos){
    int d = depthv[u]; int L = (d < CURP) ? d : d-1;
    if(pos < 1 || pos > L) return -1;
    if(pos <= CURP-1){ int node = nodeAtDepth(u, pos); return ch[node]; }
    else { int node = nodeAtDepth(u, pos+1); return ch[node]; }
}

int lcpLen(int a, int b){
    int La = (depthv[a] < CURP) ? depthv[a] : depthv[a]-1;
    int Lb = (depthv[b] < CURP) ? depthv[b] : depthv[b]-1;
    int lo = 0, hi = min(La, Lb);
    while(lo < hi){
        int mid = (lo + hi + 1) >> 1;
        auto ha = prefixHash(a, mid);
        auto hb = prefixHash(b, mid);
        if(ha == hb) lo = mid; else hi = mid - 1;
    }
    return lo;
}

bool cmpNodes(int a, int b){
    int l = lcpLen(a,b);
    int La = (depthv[a] < CURP) ? depthv[a] : depthv[a]-1;
    int Lb = (depthv[b] < CURP) ? depthv[b] : depthv[b]-1;
    if(l < min(La, Lb)){
        int ca = getCharAt(a, l+1);
        int cb = getCharAt(b, l+1);
        return ca < cb;
    } else {
        if(La != Lb) return La < Lb;
        return a < b;
    }
}

int main(){
    ios::sync_with_stdio(false); cin.tie(nullptr);

    if(!(cin >> n)) return 0;
    adj.assign(n+1, {});
    for(int i=0;i<n-1;++i){ int u,v; char c; cin >> u >> v >> c; adj[u].push_back({v, c}); adj[v].push_back({u, c}); }

    depthv.assign(n+1, 0); parentv.assign(n+1, 0); ch.assign(n+1, -1);
    maxDepth = 0; int root = 1; LOG = 0; while((1<<LOG) <= n) ++LOG; // ~19

    // BFS to root the tree at 1, compute depth, parent, and edge label
    vector<char> vis(n+1, 0); vector<int> order; order.reserve(n);
    order.push_back(root); vis[root] = 1; depthv[root] = 0; parentv[root] = 0; ch[root] = -1;
    for(size_t i=0;i<order.size();++i){ int u = order[i]; for(auto &e : adj[u]){ int v = e.first; if(vis[v]) continue; vis[v] = 1; parentv[v] = u; ch[v] = e.second - 'a'; depthv[v] = depthv[u] + 1; maxDepth = max(maxDepth, depthv[v]); order.push_back(v); } }

    // Build binary lifting table
    up.assign(LOG, vector<int>(n+1, 0));
    for(int v=1; v<=n; ++v) up[0][v] = (v==root? 0 : parentv[v]);
    for(int k=1; k<LOG; ++k) for(int v=1; v<=n; ++v) up[k][v] = up[k-1][ up[k-1][v] ];

    // Build path hashes H1/H2 along root->v
    H1.assign(n+1, 0); H2.assign(n+1, 0);
    for(int v=2; v<=n; ++v){ int p = parentv[v]; H1[v] = ( (long long) H1[p] * BASE1 + (ch[v] + 1) ) % MOD1; H2[v] = ( (long long) H2[p] * BASE2 + (ch[v] + 1) ) % MOD2; }

    // Precompute powers
    int LIM = maxDepth + 5; pow1.assign(LIM+1, 1); pow2.assign(LIM+1, 1);
    for(int i=1;i<=LIM;++i){ pow1[i] = (long long)pow1[i-1] * BASE1 % MOD1; pow2[i] = (long long)pow2[i-1] * BASE2 % MOD2; }

    // Prepare node set (all except root)
    vector<int> nodes; nodes.reserve(n-1); for(int v=2; v<=n; ++v) nodes.push_back(v);

    long long bestSize = LLONG_MAX; int bestP = 1;

    // Try all p from 1 to maxDepth
    for(int p = 1; p <= maxDepth; ++p){ CURP = p; // current p
        // If no node has depth >= p, skip (no changes)
        bool any = false; for(int v: nodes){ if(depthv[v] >= p) { any = true; break; } }
        if(!any) continue;
        vector<int> orderIdx = nodes; sort(orderIdx.begin(), orderIdx.end(), cmpNodes);
        long long sumL = 0, sumLCP = 0;
        for(int v: orderIdx){ int L = (depthv[v] < p) ? depthv[v] : depthv[v]-1; sumL += L; }
        for(size_t i=1; i<orderIdx.size(); ++i){ sumLCP += lcpLen(orderIdx[i-1], orderIdx[i]); }
        long long totalNodes = 1 + sumL - sumLCP;
        if(totalNodes < bestSize){ bestSize = totalNodes; bestP = p; }
    }

    // If nothing computed (edge case), fall back to trivial output
    if(bestSize == LLONG_MAX){ bestSize = n; bestP = 1; }

    cout << bestSize << "\n" << bestP << "\n";
    return 0;
}

