#include <bits/stdc++.h>
using namespace std;

int n;
vector<pair<int,int>> edges; // (u,v) for input i
vector<vector<pair<int,int>>> adj; // adjacency: (to, edgeIndex)
vector<int> ans; // color per edge
int R; // minimal possible r = max ceil(deg/2)
vector<int> deg;

void dfs(int v, int p, int color_parent){
    vector<pair<int,int>> children; // (to, edgeIndex)
    for(auto &e : adj[v]){
        int to = e.first; int idx = e.second;
        if(to == p) continue;
        children.push_back({to, idx});
    }
    if(p == 0){ // root
        int c1 = 1;
        int c2 = (R >= 2 ? 2 : 1);
        int cur = 0;
        for(auto &pr: children){
            int col = (cur % 2 == 0 ? c1 : c2);
            ans[pr.second] = col;
            dfs(pr.first, v, col);
            cur++;
        }
    } else {
        int c = color_parent;
        int d;
        if(R >= 2) d = (c == 1 ? 2 : 1);
        else d = c; // should not happen as R>=2 here
        int cur = 0;
        for(auto &pr: children){
            int col = (cur % 2 == 0 ? c : d);
            ans[pr.second] = col;
            dfs(pr.first, v, col);
            cur++;
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t; if(!(cin >> t)) return 0;
    while(t--){
