            deg[x]++; deg[y]++;
        }
        R = 0;
        for(int i = 1; i <= n; ++i){
            int need = (deg[i] + 1) / 2; // ceil(deg[i]/2)
            R = max(R, need);
        }
        ans.assign(n-1, 0);
        if(R == 1){
            for(int i = 0; i < n-1; ++i) ans[i] = i+1; // unique color per edge
        } else {
            dfs(1, 0, 0);
        }
