    g = [[] for _ in range(n+1)]
    for i,(u,v) in enumerate(edges):
        g[u].append((v,i)); g[v].append((u,i))
    from collections import deque
    q = deque([a])
    par = [-1]*(n+1)
    pedge = [-1]*(n+1)
    par[a] = a
    while q:
        u = q.popleft()
        if u == b:
            break
        for v, ei in g[u]:
            if par[v] == -1:
                par[v] = u
                pedge[v] = ei
                q.append(v)
    # reconstruct path edges
    path = []
    cur = b
    while cur != a:
        path.append(pedge[cur])
        cur = par[cur]
    path.reverse()
