#include <bits/stdc++.h>
using namespace std;

struct BIT {
  int n;
  vector<long long> f;
  BIT(int n=0): n(n), f(n+1,0) {}
  void init(int n_) { n = n_; f.assign(n+1,0); }
  void add(int i, long long delta){
    for(; i<=n; i += i & -i) f[i] += delta;
  }
  long long sum(int i){
    long long res = 0;
    for(; i>0; i -= i & -i) res += f[i];
    return res;
  }
  void range_add(int l, int r, long long delta){
    if(l > r) return;
    add(l, delta);
    if(r + 1 <= n) add(r + 1, -delta);
  }
};

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int n, m;
  if(!(cin >> n >> m)) return 0;
  vector<long long> a(n+1);
  for(int i=1;i<=n;i++) cin >> a[i];
  vector<vector<int>> adj(n+1);
  for(int i=0;i<n-1;i++){
    int u,v; cin >> u >> v;
    adj[u].push_back(v);
    adj[v].push_back(u);
  }

  // Euler tour: tin, tout, depth, parent (iterative DFS)
  vector<int> tin(n+1,0), tout(n+1,0), depth(n+1,0), parent(n+1,0), it(n+1,0);
  int timer = 0;
  vector<int> st;
  st.push_back(1);
  parent[1] = 0; depth[1] = 0;
  while(!st.empty()){
    int u = st.back();
    if(tin[u] == 0) tin[u] = ++timer; // first time visit
    if(it[u] < (int)adj[u].size()){
      int v = adj[u][ it[u]++ ];
      if(v == parent[u]) continue;
      parent[v] = u;
      depth[v] = depth[u] + 1;
      st.push_back(v);
    } else {
      tout[u] = timer;
      st.pop_back();
    }
  }

  // s[u] = (-1)^{depth[u]}
  vector<int> s(n+1);
  for(int i=1;i<=n;i++) s[i] = (depth[i] % 2 == 0) ? 1 : -1;

  BIT bit(n+2);

  for(int qi=0; qi<m; ++qi){
    int type; cin >> type;
    if(type == 1){
      int x; long long val; cin >> x >> val;
      long long C = val * s[x];
      int l = tin[x], r = tout[x];
      bit.range_add(l, r, C);
    } else if(type == 2){
      int x; cin >> x;
      long long T = bit.sum(tin[x]);
      long long ans = a[x] + (long long)s[x] * T;
      cout << ans << "\n";
    }
  }
  return 0;
}

