using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    if(!(cin >> n >> q)) return 0;
    vector<vector<pair<int,int>>> adj(n+1);
    for(int i = 0; i < n-1; ++i){
        int u,v,w; cin >> u >> v >> w;
        adj[u].push_back({v,w});
        adj[v].push_back({u,w});
    }
    // Root the tree at 1, build parent and children lists
    vector<int> parent(n+1, 0);
    vector<int> wpar(n+1, 0);
    vector<vector<pair<int,int>>> children(n+1);
    vector<int> order; order.reserve(n);

    // Iterative DFS to avoid recursion depth issues
    vector<int> st; st.push_back(1);
    parent[1] = -1;
    while(!st.empty()){
        int u = st.back(); st.pop_back();
        order.push_back(u);
        for(auto &e: adj[u]){
            int v = e.first, w = e.second;
            if(v == parent[u]) continue;
            parent[v] = u;
            wpar[v] = w;
            children[u].push_back({v, w});
            st.push_back(v);
        }
    }

    // Down DP: max distance from node to any node in its subtree
    vector<long long> down(n+1, 0);
    for(int i = (int)order.size()-1; i >= 0; --i){
        int u = order[i];
        long long best = 0;
        for(auto &e: children[u]){
            int v = e.first, w = e.second;
            best = max(best, (long long)w + down[v]);
        }
        down[u] = best;
    }

    // Up DP: max distance from node to any node outside its subtree
    vector<long long> up(n+1, 0);
    up[1] = 0;
    for(int idx = 0; idx < (int)order.size(); ++idx){
        int u = order[idx];
        // compute top two contributions among children: w + down[child]
        long long best1 = -1, best2 = -1; int best1Child = -1;
        for(auto &e: children[u]){
            int v = e.first, w = e.second;
            long long val = (long long)w + down[v];
            if(val > best1){ best2 = best1; best1 = val; best1Child = v; }
            else if(val > best2){ best2 = val; }
        }
        for(auto &e: children[u]){
            int v = e.first, w = e.second;
            long long useExcl = 0;
            if(best1Child == v) useExcl = max(0LL, best2);
            else useExcl = max(0LL, best1);
            long long candidate = max(up[u], useExcl);
            up[v] = (long long)w + candidate;
        }
    }

    // depths[u] will hold depth values for edges in both directions
    vector<vector<long long>> depths(n+1);
    for(int i = 2; i <= n; ++i){
        int p = parent[i]; int w = wpar[i];
        depths[p].push_back((long long)w + down[i]); // depth(p -> i)
        depths[i].push_back(up[i]);                 // depth(i -> p)
    }

