#include <bits/stdc++.h>
using namespace std;

struct Edge{ int u,v,w; };

// Brute-force solver for small trees
// Enumerates all non-empty edge subsets that form a connected subgraph,
// include at least one edge incident to x, and have at most 2*y leaves.
long long bruteSolve(int n, const vector<Edge>& edges, int x, int y){
    int m = edges.size();
    long long best = 0;
    vector<int> incidentMask(m,0);
    for(int i=0;i<m;i++) if(edges[i].u==x || edges[i].v==x) incidentMask[i]=1;

    int totalMasks = 1<<m;
    for(int mask=1; mask<totalMasks; ++mask){
        bool hasIncX=false; long long sumW=0;
        for(int i=0;i<m;i++) if(mask&(1<<i)){
            if(incidentMask[i]) hasIncX = true;
            sumW += edges[i].w;
        }
        if(!hasIncX) continue;
        // Build subgraph
        vector<int> deg(n+1,0);
        vector<vector<int>> adj(n+1);
        for(int i=0;i<m;i++) if(mask&(1<<i)){
            int u=edges[i].u, v=edges[i].v;
            deg[u]++; deg[v]++;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        // Connectivity check: all vertices with deg>0 must be connected
        int start=-1; for(int v=1; v<=n; ++v) if(deg[v]>0){ start=v; break; }
        if(start==-1) continue; // should not happen
        vector<int> vis(n+1,0); queue<int> q; q.push(start); vis[start]=1; int visCount=1;
        while(!q.empty()){
            int u=q.front(); q.pop();
            for(int nb: adj[u]) if(!vis[nb]){ vis[nb]=1; q.push(nb); visCount++; }
        }
        int totalVerts = 0; for(int v=1; v<=n; ++v) if(deg[v]>0) totalVerts++;
        if(visCount != totalVerts) continue; // not connected
        // Leaves count: number of vertices with deg==1 among included vertices
        int leaves=0; for(int v=1; v<=n; ++v) if(deg[v]>0 && deg[v]==1) leaves++;
        if(leaves > 2*y) continue;
        best = max(best, sumW);
    }
    return best;
}

