#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007LL;

long long modpow(long long a, long long e){
  long long r = 1 % MOD;
  a %= MOD;
  while(e > 0){
    if(e & 1) r = (r * a) % MOD;
    a = (a * a) % MOD;
    e >>= 1;
  }
  return r;
}
long long modinv(long long a){ return modpow(a, MOD - 2); }

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int N, K;
  if(!(cin >> N >> K)) return 0;
  vector<int> a(K);
  for(int i = 0; i < K; ++i) cin >> a[i];

  // Precompute factorials and inverse factorials up to N
  vector<long long> fact(N + 1), invfact(N + 1);
  fact[0] = 1;
  for(int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;
  invfact[N] = modinv(fact[N]);
  for(int i = N; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

  // DP over sums of s_t
  vector<long long> dp(N + 1, 0), ndp(N + 1, 0);
  dp[0] = 1;

  for(int t = 0; t < K; ++t){
    int av = a[t];
    // precompute f_t[s] for s = 0..av
    vector<long long> f(av + 1);
    for(int s = 0; s <= av; ++s){
      long long val = fact[av];
      val = val * fact[N - s] % MOD;
      val = val * invfact[s] % MOD;
      val = val * invfact[av - s] % MOD;
      f[s] = val;
    }

    fill(ndp.begin(), ndp.end(), 0);
    for(int sum = 0; sum <= N; ++sum){
      if(dp[sum] == 0) continue;
      for(int s = 0; s <= av && sum + s <= N; ++s){
        ndp[sum + s] = (ndp[sum + s] + dp[sum] * f[s]) % MOD;
      }
    }
    dp.swap(ndp);
  }

  long long ans = dp[N];
  long long Nfact = fact[N];
  long long factor;
  int exp = 1 - K; // exponent for Nfact
  if(exp >= 0){
    factor = modpow(Nfact, exp);
  } else {
    long long p = modpow(Nfact, -exp);
    factor = modinv(p);
  }
  ans = (ans * factor) % MOD;
  cout << ans << '\n';
  return 0;
}
