#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

struct Fruit { int day; ll w; };

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if(!(cin >> n >> m >> k)) return 0;
    vector<vector<int>> children(n+1);
    vector<int> parent(n+1, 0);
    for(int i=2;i<=n;i++){
        int p; cin >> p; parent[i]=p; children[p].push_back(i);
    }
    vector<Fruit> fruit(n+1, {0, 0}); // 0 means no fruit
    for(int j=0;j<m;j++){
        int v,d; ll w; cin >> v >> d >> w;
        // Each vertex has at most one fruit; store it
        fruit[v] = {d, w};
    }

    // DFS with small-to-large maps
    vector< unordered_map<int,ll> > dp(n+1);
    vector<char> vis(n+1, 0);

    function<void(int)> dfs = [&](int u){
        vis[u] = 1;
        // Start map with this node's fruit if any
        if(fruit[u].day != 0){
            dp[u].reserve(2);
            dp[u][fruit[u].day] = fruit[u].w;
        }
        // Merge children maps into current node using small-to-large
        for(int v: children[u]){
            dfs(v);
            // Merge dp[v] into dp[u]
            if(dp[v].empty()) continue;
            if(dp[u].size() < dp[v].size()) dp[u].reserve(dp[v].size() + dp[u].size());
            // Always merge smaller into larger for efficiency
            if(dp[u].size() < dp[v].size()) swap(dp[u], dp[v]);
            for(auto &kv : dp[v]){
                int day = kv.first; ll val = kv.second;
                dp[u][day] += val; // accumulate per-day fruit yield from child subtree
            }
        }
    };

    dfs(1);
    ll ans = 0;
    // The answer is the maximum total juice we can harvest by day across the root's merged map
    for(auto &p : dp[1]) ans = max(ans, p.second);
    cout << ans << "\n";
    return 0;
}

