    map<u64,int> mfact;
    factorAll(m, mfact);
    vector<u64> primes;
    vector<int> exps;
    for (auto &kv : mfact) {
        primes.push_back(kv.first);
        exps.push_back(kv.second);
    }
    int k = (int)primes.size();

    unsigned long long answer = 0ull;
    vector<int> curExp(k, 0);

    function<void(int, u64)> dfs = [&](int idx, u64 t){
        if (idx == k) {
            u64 phi = 1;
            u64 ord_t = 1;
            bool hasExp = false;
            for (int i = 0; i < k; ++i) {
                int e = curExp[i];
                if (e > 0) {
                    u64 p = primes[i];
                    u64 pe_1 = 1;
                    for (int j = 1; j < e; ++j) pe_1 *= p;
                    phi *= pe_1 * (p - 1);
                    u64 ord_i = ord_mod_p_power(x, p, e);
                    ord_t = lcm_u64(ord_t, ord_i);
                    hasExp = true;
                }
            }
            if (!hasExp) {
                phi = 1;
                ord_t = 1;
            }
            answer += phi / ord_t;
            return;
        }
        u64 p = primes[idx];
        u64 val = 1;
        for (int e = 0; e <= exps[idx]; ++e) {
            curExp[idx] = e;
            dfs(idx + 1, t * val);
            val *= p;
        }
    };

    dfs(0, 1ull);

    cout << answer << "\n";
    return 0;
}
