#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n; 
    vector<long long> bit;
    Fenwick(int n0=0){ init(n0); }
    void init(int n0){ n = n0; bit.assign(n+1, 0); }
    void add(int idx, long long delta){ for (int i=idx; i<=n; i += i & -i) bit[i] += delta; }
    long long sum(int idx){ long long s = 0; for (int i = idx; i > 0; i -= i & -i) s += bit[i]; return s; }
    // smallest index such that prefix sum >= k (1-based). assumes 1 <= k <= sum(n)
    int kth(long long k){ int idx = 0; int bitMask = 1; while ((bitMask<<1) <= n) bitMask <<= 1; for (int d = bitMask; d; d >>= 1){ int next = idx + d; if (next <= n && bit[next] < k){ idx = next; k -= bit[next]; } } return idx + 1; }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int C; if(!(cin >> C)) return 0;
    while (C--) {
        int n, m; long long T; cin >> n >> m >> T;
