        for (int i = 1; i <= n; ++i) arr.emplace_back(p[i], i);
        sort(arr.begin(), arr.end());

        Fenwick cnt(n), sum(n);
        long long best_k = 0;
        int best_d = 1; // default if k==0

        for (size_t i = 0; i < arr.size(); ) {
            int val = arr[i].first;
            // activate all indices with this value
            while (i < arr.size() && arr[i].first == val) {
                int idx = arr[i].second;
                cnt.add(idx, 1);
                sum.add(idx, val);
                ++i;
            }
            // helper to compute F(s): sum of first s active elements
            auto F = [&](int s)->long long {
                if (s <= 0) return 0LL;
                int total = (int)cnt.sum(n);
                if (s > total) s = total; // clamp to total active
                if (s <= 0) return 0LL;
                int pos = cnt.kth(s); // position of s-th active
                return sum.sum(pos);
            };

            long long k_here = 0;
            int L = (int)cnt.sum(n);
            if (L == 0) {
                // nothing active yet
                if (best_k == 0) best_d = 1; // keep default for k==0
                continue;
            }
            if (m == 1) {
                int lo = 0, hi = L;
                while (lo < hi) {
                    int mid = (lo + hi + 1) / 2;
                    long long Fmid = F(mid);
                    if (2LL * Fmid <= T) lo = mid; else hi = mid - 1;
                }
                k_here = lo;
            } else {
                long long bestLocal = 0;
                for (int q = 0; q <= L / m; ++q) {
                    long long Sq = F(q * m);
                    long long rem = T - Sq;
                    if (rem < 0) break;
                    int Kmax = min((long long)q * m + m - 1, (long long)L);
