        vector<pair<int,int>> arr; arr.reserve(n);
        for (int i = 1; i <= n; ++i) arr.emplace_back(p[i], i);
        sort(arr.begin(), arr.end());

        Fenwick cnt(n), sum(n);
        long long best_k = 0;
        int best_d = 1; // default

        for (size_t i = 0; i < arr.size(); ) {
            int val = arr[i].first;
            while (i < arr.size() && arr[i].first == val) {
                int idx = arr[i].second;
                cnt.add(idx, 1);
                sum.add(idx, val);
                ++i;
            }
            auto F = [&](int s)->long long {
                if (s <= 0) return 0LL;
                int total = (int)cnt.sum(n);
                if (s > total) s = total;
                if (s <= 0) return 0LL;
                int pos = cnt.kth(s);
                return sum.sum(pos);
            };
            int L = (int)cnt.sum(n);
            if (L == 0) continue;

            long long k_here = 0;
            if (m == 1) {
                int lo = 0, hi = L;
                while (lo < hi) {
