#include <bits/stdc++.h>
using namespace std;

struct SegTree {
    int n;
    vector<int> sum;
    vector<char> lazy;
    SegTree() {}
    SegTree(const vector<int>& a) { build(a); }
    void build(const vector<int>& a) {
        n = (int)a.size() - 1; // a is 1-indexed with size n+1
        sum.assign(4*n + 5, 0);
        lazy.assign(4*n + 5, 0);
        build(1, 1, n, a);
    }
    void build(int p, int l, int r, const vector<int>& a) {
        if (l == r) { sum[p] = a[l]; return; }
        int m = (l + r) >> 1;
        build(p<<1, l, m, a);
        build(p<<1|1, m+1, r, a);
        sum[p] = sum[p<<1] + sum[p<<1|1];
    }
    inline void apply(int p, int l, int r) {
        sum[p] = (r - l + 1) - sum[p];
        lazy[p] ^= 1;
    }
    inline void push(int p, int l, int r) {
        if (lazy[p]) {
            int m = (l + r) >> 1;
            apply(p<<1, l, m);
            apply(p<<1|1, m+1, r);
            lazy[p] = 0;
        }
    }
    void update(int p, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) { apply(p, l, r); return; }
        push(p, l, r);
        int m = (l + r) >> 1;
        update(p<<1, l, m, ql, qr);
        update(p<<1|1, m+1, r, ql, qr);
        sum[p] = sum[p<<1] + sum[p<<1|1];
    }
    int query(int p, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) return sum[p];
        push(p, l, r);
        int m = (l + r) >> 1;
        return query(p<<1, l, m, ql, qr) + query(p<<1|1, m+1, r, ql, qr);
    }
    // wrappers
    void update(int l, int r) { update(1, 1, n, l, r); }
    int query(int l, int r) { return query(1, 1, n, l, r); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

