        sort(intervals.begin(), intervals.end(), [](const Interval& a, const Interval& b){ if(a.l!=b.l) return a.l < b.l; return a.r < b.r; });
        long double total = 0.0L;
        long double curL = intervals[0].l, curR = intervals[0].r;
        for(size_t idx=1; idx<intervals.size(); ++idx){
            if(intervals[idx].l > curR){ total += curR - curL; curL = intervals[idx].l; curR = intervals[idx].r; }
