            if (R <= L + 1e-18L) continue;
            long double xA = L + (R - L)/3.0L; // interior point 1
            long double xB = L + 2.0L*(R - L)/3.0L; // interior point 2
            long double LA = union_length_at(xA);
            long double LB = union_length_at(xB);
            area_union += (R - L) * (LA + LB) * 0.5L; // trapezoid rule for linear function
        }
    }

