static inline long double cross_ld(long double ax, long double ay, long double bx, long double by){ return ax*by - ay*bx; }
static inline long double cross(const P& a, const P& b, const P& c){ // (b-a) x (c-a)
    return cross_ld(b.x - a.x, b.y - a.y, c.x - a.x, c.y - a.y);
