            LLPoint q1 = edges[j].a, q2 = edges[j].b;
            long long x1 = p1.x, y1 = p1.y, x2 = p2.x, y2 = p2.y;
            long long x3 = q1.x, y3 = q1.y, x4 = q2.x, y4 = q2.y;
            // orientations
            auto orient = [&](long long ax, long long ay, long long bx, long long by, long long cx, long long cy){ long long v = (bx-ax)*(cy-ay) - (by-ay)*(cx-ax); if(v>0) return 1; if(v<0) return -1; return 0; };
            int o1 = orient(x1,y1,x2,y2,x3,y3);
            int o2 = orient(x1,y1,x2,y2,x4,y4);
            int o3 = orient(x3,y3,x4,y4,x1,y1);
            int o4 = orient(x3,y3,x4,y4,x2,y2);
