            if(o1==0 && on_segment_ll(p1,p2,q1)) xs_set.insert((long double)x3);
            if(o2==0 && on_segment_ll(p1,p2,q2)) xs_set.insert((long double)x4);
            if(o3==0 && on_segment_ll(q1,q2,p1)) xs_set.insert((long double)x1);
