            else { if(ivs[i].r > curR) curR = ivs[i].r; }
        }
        total += curR - curL;
        return total;
    };

    long double area_union = 0.0L;
    if(xs.size() >= 2){
        for(size_t i=0;i+1<xs.size();++i){
            long double L = xs[i], R = xs[i+1];
            if(R <= L) continue;
            long double x1 = L + (R - L)/3.0L;
            long double x2 = L + 2.0L*(R - L)/3.0L;
            long double L1 = union_length_at(x1);
            long double L2 = union_length_at(x2);
            area_union += (R - L) * (L1 + L2) * 0.5L;
        }
    }

    long double E = 0.0L;
    if(area_union > 0) E = area_sum / area_union; else E = 0.0L;

    cout.setf(std::ios::fixed); cout<<setprecision(10)<<(double)E<<"\n";
    return 0;
}
