        void init(const vector<int>& a){ n = (int)a.size(); st.assign(4*n, GLOBAL_NEG); if(n>0) build(1,0,n-1,a); }
        void build(int p, int l, int r, const vector<int>& a){ if(l==r){ st[p] = a[l]; return; } int m=(l+r)>>1; build(p<<1,l,m,a); build(p<<1|1,m+1,r,a); st[p] = max(st[p<<1], st[p<<1|1]); }
        void update(int idx, int val){ update(1,0,n-1,idx,val); }
        void update(int p, int l, int r, int idx, int val){ if(l==r){ st[p] = val; return; } int m=(l+r)>>1; if(idx<=m) update(p<<1,l,m,idx,val); else update(p<<1|1,m+1,r,idx,val); st[p] = max(st[p<<1], st[p<<1|1]); }
        int query(int L, int R){ if(L>R) return GLOBAL_NEG; return query(1,0,n-1,L,R); }
        int query(int p, int l, int r, int L, int R){ if(R<l || r<L) return GLOBAL_NEG; if(L<=l && r<=R) return st[p]; int m=(l+r)>>1; return max(query(p<<1,l,m,L,R), query(p<<1|1,m+1,r,L,R)); }
    } seg;
