        int v = trie[0].nxt[c];
        if(v != -1){ link[v] = 0; q.push(v); }
        else trie[0].nxt[c] = 0;
    }
    while(!q.empty()){
        int v = q.front(); q.pop();
        for(int c=0;c<26;++c){
            int u = trie[v].nxt[c];
            if(u != -1){
                link[u] = trie[link[v]].nxt[c];
