                trie[v].nxt[c] = trie[link[v]].nxt[c];
            }
        }
    }

    // Build fail tree
    vector<vector<int>> failTree(N);
    for(int v=1; v<N; ++v){ int p = link[v]; failTree[p].push_back(v); }

    // Heavy-Light Decomposition on fail tree
    vector<int> parent(N, -1), depth(N, 0), heavy(N, -1), sz(N, 0);
    function<int(int)> dfs = [&](int v){
        sz[v] = 1; int maxsz = 0;
        for(int u : failTree[v]){
