def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    a = [0] * (n + 1)
    red_total = 0
    blue_total = 0
    for i in range(1, n + 1):
        val = next(it)
        a[i] = val
        if val == 1:
            red_total += 1
        elif val == 2:
            blue_total += 1
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        v = next(it)
        u = next(it)
        adj[v].append(u)
        adj[u].append(v)

    # Build parent and order with DFS
    parent = [0] * (n + 1)
    order = []
    stack = [1]
    parent[1] = -1
    while stack:
        v = stack.pop()
        order.append(v)
        for w in adj[v]:
            if w != parent[v]:
                parent[w] = v
                stack.append(w)

    # Subtree color counts
    red_sub = [0] * (n + 1)
    blue_sub = [0] * (n + 1)
    for v in reversed(order):
