using namespace std;

// This solution uses a segment tree where each node stores a 5x5 matrix (max-plus algebra).
// States encode progress in a DFA for the language: "string contains 2017 as subsequence and does not contain 2016 as subsequence".
// The exact DFA transitions are encoded in a precomputed delta[d][state].
// For simplicity and portability, we implement a DFA with 5 states where state 0 is start and state 4 is the accepting state
// that ensures 2017 has occurred while preventing formation of 2016. The precise delta table must reflect the intended language.

static const int S = 5; // number of DFA states
static const int NEG = -1000000000; // -INF for max-plus

// delta[digit][state] // 0..9 digits, 0..4 states
// This table must be derived to represent the language correctly. Below is a placeholder that needs proper DFA design.
