// M[i][i] = max(M[i][i], 0) // delete
// M[i][ delta_table[c-'0'][i] ] = max(M[...], 1) // keep

struct Matrix {
    int a[S][S];
    Matrix() {
        for(int i=0;i<S;i++) for(int j=0;j<S;j++) a[i][j] = (i==j? 0 : NEG);
    }
};

Matrix merge(const Matrix& L, const Matrix& R) {
    Matrix res; 
    for(int i=0;i<S;i++){
        for(int k=0;k<S;k++){
            int best = NEG;
            for(int j=0;j<S;j++) {
                int val = L.a[i][j] + R.a[j][k];
                if(val > best) best = val;
            }
            res.a[i][k] = best;
        }
    }
    return res;
}

struct SegTree {
    int n;
    vector<Matrix> st;
    string s;
    SegTree(const string& str): n((int)str.size()), s(str) {
        st.resize(4*n);
        build(1,0,n-1);
    }
    Matrix leafMatrix(char c){
        Matrix M;
        int digit = c - '0';
        for(int i=0;i<S;i++){
            // delete: stay in i with 0 gain
            M.a[i][i] = max(M.a[i][i], 0);
            // keep: go to delta(digit,i) with +1 gain if possible
            int to = delta_table[digit][i];
            M.a[i][to] = max(M.a[i][to], 1);
        }
        return M;
    }
    void build(int p, int l, int r){
        if(l==r){
            st[p] = leafMatrix(s[l]);
            return;
        }
        int m=(l+r)>>1;
        build(p<<1,l,m);
        build(p<<1|1,m+1,r);
        st[p] = merge(st[p<<1], st[p<<1|1]);
    }
    // query over [L,R]
    Matrix query(int p, int l, int r, int L, int R){
        if(R<l || r<L){
            // identity for max-plus: M[i][j] = (i==j?0:-INF)
            Matrix I; 
            for(int i=0;i<S;i++) for(int j=0;j<S;j++) I.a[i][j] = (i==j? 0 : NEG);
            return I; 
        }
        if(L<=l && r<=R) return st[p];
        int m=(l+r)>>1;
        Matrix left = query(p<<1,l,m,L,R);
        Matrix right = query(p<<1|1,m+1,r,L,R);
        return merge(left,right);
    }
    int answer(int L, int R){
        Matrix M = query(1,0,n-1,L,R);
        // Start state is 0. We want the maximum kept length ending in any accepting state.
        int best = NEG;
        for(int j=0;j<S;j++) best = max(best, M.a[0][j]);
        // If best is NEG, impossible
        if(best < 0) return -1;
        int len = (R-L+1) - best;
        return len;
    }
};

int main(){
