#include <bits/stdc++.h>
using namespace std;

struct SuffixAutomaton {
  struct State {
    int next[26];
    int link;
    int len;
    long long occ;
    State() { memset(next, -1, sizeof(next)); link = -1; len = 0; occ = 0; }
  };
  vector<State> st; int last;
  SuffixAutomaton(int maxStates=0){ if(maxStates) st.reserve(maxStates); st.push_back(State()); last = 0; }
  void extend(int c){
    int cur = (int)st.size();
    st.push_back(State());
    st[cur].len = st[last].len + 1;
    st[cur].occ = 1;
    int p = last;
    while(p != -1 && st[p].next[c] == -1){
      st[p].next[c] = cur;
      p = st[p].link;
    }
    if(p == -1){
      st[cur].link = 0;
    } else {
      int q = st[p].next[c];
      if(st[p].len + 1 == st[q].len){
        st[cur].link = q;
      } else {
        int clone = (int)st.size();
        st.push_back(st[q]);
        st[clone].len = st[p].len + 1;
        st[clone].occ = 0;
        while(p != -1 && st[p].next[c] == q){
          st[p].next[c] = clone;
          p = st[p].link;
        }
        st[q].link = st[cur].link = clone;
      }
    }
    last = cur;
  }
  void buildEndpos(){
    int maxLen = 0;
    for(auto &s : st) maxLen = max(maxLen, s.len);
    vector<int> cnt(maxLen+1);
    for(auto &s : st) cnt[s.len]++;
    for(int i=1; i<=maxLen; ++i) cnt[i] += cnt[i-1];
    vector<int> order(st.size());
    for(int i=(int)st.size()-1; i>=0; --i){ order[--cnt[st[i].len]] = i; }
    for(int i=(int)st.size()-1; i>0; --i){ int v = order[i]; int p = st[v].link; if(p >= 0) st[p].occ += st[v].occ; }
  }
};

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  string s; if(!(cin>>s)) return 0;
  int n; cin>>n;
  vector<string> queries(n); for(int i=0;i<n;++i) cin>>queries[i];

  int maxStates = 2*(int)s.size() + 5;
  SuffixAutomaton sam(maxStates);
  for(char ch: s) sam.extend(ch - 'a');
  sam.buildEndpos();

  const unsigned long long B = 1315423911ULL;
  for(int qi=0; qi<n; ++qi){
    const string &x = queries[qi]; int m = (int)x.size();
    string t = x + x; int L = (int)t.size();
    vector<unsigned long long> H(L+1, 0), P(L+1, 0); P[0] = 1;
    for(int i=0;i<L;++i){ H[i+1] = H[i]*B + (unsigned long long)(t[i]-'a'+1); P[i+1] = P[i]*B; }
    auto getHash = [&](int l, int r){ return H[r+1] - H[l]*P[r-l+1]; };
    int v = 0, l = 0; unordered_set<unsigned long long> seen; long long ans = 0;
    for(int j=0; j<L; ++j){
      int c = t[j]-'a';
      while(v != -1 && sam.st[v].next[c] == -1){
        v = sam.st[v].link; if(v != -1) l = sam.st[v].len; else l = 0;
      }
      if(v == -1){ v = 0; l = 0; } else { v = sam.st[v].next[c]; ++l; }
      if(j >= m-1){
        if(l >= m){
          int u = v;
          while(sam.st[u].link != -1 && sam.st[sam.st[u].link].len >= m) u = sam.st[u].link;
          int start = j - m + 1;
          unsigned long long h = getHash(start, j);
          if(seen.insert(h).second){ ans += sam.st[u].occ; }
        }
      }
    }
    cout << ans << '\n';
  }
  return 0;
}
