// Build a simple undirected tree with edges (u, v, a, b)
// On day t, weight = a * t + b

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; long long m;
    if(!(cin >> n >> m)) return 0;
    vector<vector<Edge>> g(n + 1);
    for(int i = 0; i < n - 1; ++i) {
        int u, v; long long a, b;
        cin >> u >> v >> a >> b;
        g[u].push_back({v, a, b});
        g[v].push_back({u, a, b});
    }

    auto dist_from = [&](int start, long long t) {
        vector<long long> dist(n + 1, -1);
        vector<int> st;
        st.push_back(start);
        dist[start] = 0;
        while(!st.empty()) {
            int u = st.back(); st.pop_back();
            for(const auto &e : g[u]) {
                int v = e.to;
                long long w = e.a * t + e.b;
                if(dist[v] == -1) {
                    dist[v] = dist[u] + w;
                    st.push_back(v);
                }
            }
        }
        int far = start;
        long long best = -1;
        for(int i = 1; i <= n; ++i) {
            if(dist[i] > best) { best = dist[i]; far = i; }
        }
        return make_pair(far, dist);
    };

    vector<long long> ans;
    ans.reserve(m);
    for(long long t = 0; t < m; ++t) {
        auto r1 = dist_from(1, t);
        int a = r1.first;
        auto r2 = dist_from(a, t);
        long long diam = -1;
        for(int i = 1; i <= n; ++i) diam = max(diam, r2.second[i]);
        ans.push_back(diam);
    }

    for(size_t i = 0; i < ans.size(); ++i) {
        if(i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}
