#ifndef LICHAO_H
#define LICHAO_H
#include <bits/stdc++.h>
using namespace std;

// Dynamic Li Chao Tree for maximum of lines on domain [X_MIN, X_MAX]
struct LiChao {
    struct Line { long long m, b; Line(long long _m=0, long long _b=LLONG_MIN/4): m(_m), b(_b) {};
        long long value(long long x) const { return m * x + b; }
    };
    struct Node {
        Line f; Node *l, *r;
        Node(Line _f): f(_f), l(nullptr), r(nullptr) {}
    };
    long long X_MIN, X_MAX;
    Node* root;
    LiChao(long long xmin, long long xmax): X_MIN(xmin), X_MAX(xmax), root(nullptr) {}
    void addLine(Line nw) { addLine(root, X_MIN, X_MAX, nw); }
    long long query(long long x) const { return query(root, X_MIN, X_MAX, x); }
private:
    void addLine(Node* &node, long long l, long long r, Line nw) {
        if(!node){ node = new Node(nw); return; }
        long long mid = (l + r) >> 1;
        bool leftBetter = nw.value(l) > node->f.value(l);
        bool midBetter = nw.value(mid) > node->f.value(mid);
        if(midBetter) swap(node->f, nw);
        if(l == r) return;
        if(leftBetter != midBetter) addLine(node->l, l, mid, nw);
        else addLine(node->r, mid+1, r, nw);
    }
    long long query(Node* node, long long l, long long r, long long x) const {
        if(!node) return LLONG_MIN/4;
        long long res = node->f.value(x);
        if(l == r) return res;
        long long mid = (l + r) >> 1;
        if(x <= mid) return max(res, query(node->l, l, mid, x));
        else return max(res, query(node->r, mid+1, r, x));
    }
};

#endif
