#include <bits/stdc++.h>
using namespace std;

// BFS helper: find farthest node from start, fill dist with distances
int bfsFarthest(int start, vector<int>& dist, const vector<vector<int>>& g) {
    fill(dist.begin(), dist.end(), -1);
    queue<int> q; dist[start] = 0; q.push(start);
    int far = start;
    while(!q.empty()) {
        int u = q.front(); q.pop();
        if (dist[u] > dist[far]) far = u;
        for (int v : g[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return far;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    if(!(cin >> n >> m >> q)) return 0;
    vector<vector<int>> g(n);
    for (int i = 0; i < m; ++i) {
        int u, v; cin >> u >> v; --u; --v;
        g[u].push_back(v); g[v].push_back(u);
