    vector<vector<int>> ecc;            // per component: sorted eccentricities
    vector<vector<long long>> pref;     // per component: prefix sums of ecc
    vector<int> dia;                      // per component: diameter
    int compCnt = 0;
    vector<int> dist(n, -1), distS(n, -1), distT(n, -1);

    for (int i = 0; i < n; ++i) {
        if (compId[i] != -1) continue;
        // collect this component via BFS
        vector<int> compNodes; queue<int> qu; qu.push(i); compId[i] = compCnt;
        while(!qu.empty()) {
            int u = qu.front(); qu.pop(); compNodes.push_back(u);
            for (int v : g[u]) if (compId[v] == -1) { compId[v] = compCnt; qu.push(v); }
        }

        // diameter endpoints by two BFS traversals
        int s = bfsFarthest(compNodes[0], dist, g);
        int t = bfsFarthest(s, distS, g);
        int D = distS[t];
        bfsFarthest(t, distT, g);

        // eccentricities for all nodes in this component
        vector<int> eccVec; eccVec.reserve(compNodes.size());
        for (int node : compNodes) {
            int e = max(distS[node], distT[node]);
            eccVec.push_back(e);
        }
        sort(eccVec.begin(), eccVec.end());
        vector<long long> prefVec(eccVec.size());
        long long acc = 0;
        for (size_t k = 0; k < eccVec.size(); ++k) {
            acc += eccVec[k];
            prefVec[k] = acc;
        }
        ecc.push_back(move(eccVec));
        pref.push_back(move(prefVec));
        dia.push_back(D);
        compCnt++;
    }

    unordered_map<long long, double> memo; memo.reserve((size_t)q * 2);

    auto computePair = [&](int a, int b) -> double {
        if (a == b) return -1.0; // same component
        int i = a, j = b;
        if (i > j) swap(i, j);
        long long key = ((long long)i << 32) | (unsigned long long) j;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        const vector<int>& vecI = ecc[i];
        const vector<int>& vecJ = ecc[j];
        bool useIasA = (vecI.size() <= vecJ.size());
        const vector<int>* pA = useIasA ? &vecI : &vecJ;
        const vector<int>* pB = useIasA ? &vecJ : &vecI;
        int base = max(dia[i], dia[j]);
        const vector<int>& A = *pA;
        const vector<int>& B = *pB;
