            long long sumYgt = sumB - sumFirst;
            long long mB = (long long)B.size();
            long long mminus = mB - idx;
            total += (double)idx * base + (double)mminus * (x + 1) + (double)sumYgt;
        }
        double ans = total / ((double)A.size() * (double)B.size());
        memo[key] = ans;
        return ans;
    };

