#include <bits/stdc++.h>
using namespace std;

// BFS helper: find farthest node from start, fill dist with distances
int bfsFarthest(int start, vector<int>& dist, const vector<vector<int>>& g) {
    fill(dist.begin(), dist.end(), -1);
    queue<int> q; dist[start] = 0; q.push(start);
    int far = start;
    while(!q.empty()) {
        int u = q.front(); q.pop();
        if (dist[u] > dist[far]) far = u;
        for (int v : g[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return far;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    if(!(cin >> n >> m >> q)) return 0;
    vector<vector<int>> g(n);
    for (int i = 0; i < m; ++i) {
        int u, v; cin >> u >> v; --u; --v;
        g[u].push_back(v); g[v].push_back(u);
    }

    vector<int> compId(n, -1);
    vector<vector<int>> ecc;            // per component: sorted eccentricities
    vector<vector<long long>> pref;     // per component: prefix sums of ecc
    vector<int> dia;                      // per component: diameter
    int compCnt = 0;
    vector<int> dist(n, -1), distS(n, -1), distT(n, -1);

    for (int i = 0; i < n; ++i) {
        if (compId[i] != -1) continue;
        // collect this component via BFS
        vector<int> compNodes; queue<int> qu; qu.push(i); compId[i] = compCnt;
        while(!qu.empty()) {
            int u = qu.front(); qu.pop(); compNodes.push_back(u);
            for (int v : g[u]) if (compId[v] == -1) { compId[v] = compCnt; qu.push(v); }
        }

        // diameter endpoints by two BFS traversals
        int s = bfsFarthest(compNodes[0], dist, g);
        int t = bfsFarthest(s, distS, g);
        int D = distS[t];
        bfsFarthest(t, distT, g);

        // eccentricities for all nodes in this component
        vector<int> eccVec; eccVec.reserve(compNodes.size());
        for (int node : compNodes) {
            int e = max(distS[node], distT[node]);
            eccVec.push_back(e);
        }
        sort(eccVec.begin(), eccVec.end());
        vector<long long> prefVec(eccVec.size());
        long long acc = 0;
        for (size_t k = 0; k < eccVec.size(); ++k) {
            acc += eccVec[k];
            prefVec[k] = acc;
        }
        ecc.push_back(move(eccVec));
        pref.push_back(move(prefVec));
        dia.push_back(D);
        compCnt++;
    }

    unordered_map<long long, double> memo; memo.reserve((size_t)q * 2);

    auto computePair = [&](int a, int b) -> double {
        if (a == b) return -1.0; // same component
        int i = a, j = b;
        if (i > j) swap(i, j);
        long long key = ((long long)i << 32) | (unsigned long long) j;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        const vector<int>& Ei = ecc[i];
        const vector<int>& Ej = ecc[j];
        bool AisI = (Ei.size() <= Ej.size());
        const vector<int>& A = AisI ? Ei : Ej;
        const vector<int>& B = AisI ? Ej : Ei;
        int base = max(dia[i], dia[j]);
        const vector<long long>& prefB = AisI ? pref[j] : pref[i];
        long long sumB = prefB.back();
        double total = 0.0;
        for (int x : A) {
            int t = base - x - 1;
            int cnt = upper_bound(B.begin(), B.end(), t) - B.begin();
            long long sumFirst = (cnt > 0) ? prefB[cnt - 1] : 0;
            long long mB = (long long)B.size();
            long long mminus = mB - cnt;
            long long sumY = sumB - sumFirst;
            total += (double)cnt * base + (double)mminus * (x + 1) + (double)sumY;
        }
        double ans = total / ((double)A.size() * (double)B.size());
        memo[key] = ans;
        return ans;
    };

    cout.setf(std::ios::fixed); cout << setprecision(10);
    for (int qi = 0; qi < q; ++qi) {
        int u, v; cin >> u >> v; --u; --v;
        int cu = compId[u], cv = compId[v];
        if (cu == cv) {
            cout << -1 << "\n";
        } else {
            double ans = computePair(cu, cv);
            cout << ans << "\n";
        }
    }
    return 0;
}
