    while line is not None and line.strip() == '':
        line = sys.stdin.readline()
        if line is None:
            break
    if not line:
        print(0)
        return
    P, M = map(int, line.strip().split())
    maxP = P

    class Node:
        __slots__ = ('val', 'left', 'right', 'dp')
        def __init__(self, val=None, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right
            self.dp = None

    idx = 0
    def parse():
        nonlocal idx
        if s[idx] == '(':
            idx += 1  # skip '('
            left = parse()
            idx += 1  # skip '?'
            right = parse()
            idx += 1  # skip ')'
            return Node(left=left, right=right)
        else:
