      "keystrokes": "cat > main.cpp <<'CPP'
#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin >> n)) return 0;
    vector<int> a(n);
    int maxA = 0;
    for(int i = 0; i < n; ++i){ cin >> a[i]; maxA = max(maxA, a[i]); }

    // SPF sieve up to maxA
    int limit = max(2, maxA);
    vector<int> spf(limit + 1, 0);
    for(int i = 2; i <= limit; ++i){
        if(spf[i] == 0){
            spf[i] = i;
            if((long long)i * i <= limit){
                for(long long j = 1LL * i * i; j <= limit; j += i){
                    if(spf[j] == 0) spf[j] = i;
                }
            }
        }
    }

    // Factorize each a[i]
    vector<vector<pair<int,int>>> fac(n);
    for(int i = 0; i < n; ++i){
        int x = a[i];
        if(x <= 1) continue; // 1 has no prime factors
        while(x > 1){
            int p = spf[x];
            int cnt = 0;
            while(x % p == 0){ x /= p; ++cnt; }
            fac[i].push_back({p, cnt});
        }
    }

    int q; cin >> q;
    long long last = 0; // last answer (mod 1e9+7)

    for(int qi = 0; qi < q; ++qi){
        long long x, y; cin >> x >> y;
        int l = (int)((last + x) % n); // 0-based after mod and no +1 (we convert later)
        int r = (int)((last + y) % n);
        if(l > r) swap(l, r);

        // Compute LCM on a[l..r] by taking max exponent per prime
        unordered_map<int,int> mp;
        mp.reserve((r - l + 1) * 2);
        for(int i = l; i <= r; ++i){
            for(auto &pe : fac[i]){
                int p = pe.first, e = pe.second;
                auto it = mp.find(p);
                if(it == mp.end()) mp.emplace(p, e);
                else if(e > it->second) it->second = e;
            }
        }

        long long ans = 1;
        auto modpow = [&](long long a, long long e){
            long long res = 1 % MOD;
            a %= MOD;
            while(e > 0){
                if(e & 1) res = (res * a) % MOD;
                a = (a * a) % MOD;
                e >>= 1;
            }
            return res;
        };
        for(auto &kv : mp){
            ans = (ans * modpow(kv.first, kv.second)) % MOD;
        }
        cout << ans << "\n";
        last = ans; // update last for next query
    }

    return 0;
}
