        for (int i = 0; i < N; ++i) {
            long long x, y; cin >> x >> y;
            win[i] = {x, y};
        }
        vector<Pt> curtain(4);
        for (int j = 0; j < 4; ++j) {
            long long a, b; cin >> a >> b;
            curtain[j] = {a, b};
        }
        long long xmin_rect = curtain[0].x, xmax_rect = curtain[0].x;
        long long ymin_rect = curtain[0].y, ymax_rect = curtain[0].y;
        for (int j = 0; j < 4; ++j) {
            xmin_rect = min(xmin_rect, curtain[j].x);
            xmax_rect = max(xmax_rect, curtain[j].x);
            ymin_rect = min(ymin_rect, curtain[j].y);
            ymax_rect = max(ymax_rect, curtain[j].y);
        }

        // Area of window using shoelace
        long long area2 = 0;
        for (int i = 0; i < N; ++i) {
            int j = (i + 1) % N;
            area2 += win[i].x * win[j].y - win[j].x * win[i].y;
        }
        if (area2 < 0) area2 = -area2;
        long long area_window = area2 / 2; // integer as per problem statement

        // Build horizontal edges of window
        struct Hor { long long y; long long x1, x2; };
        vector<Hor> horiz;
        for (int i = 0; i < N; ++i) {
            int j = (i + 1) % N;
            if (win[i].y == win[j].y) {
                long long y = win[i].y;
                long long x1 = min(win[i].x, win[j].x);
                long long x2 = max(win[i].x, win[j].x);
                horiz.push_back({y, x1, x2});
            }
        }

        // Slabs along x
        vector<long long> xs;
        xs.reserve(N + 2);
        for (int i = 0; i < N; ++i) xs.push_back(win[i].x);
        xs.push_back(xmin_rect);
        xs.push_back(xmax_rect);
        sort(xs.begin(), xs.end());
        xs.erase(unique(xs.begin(), xs.end()), xs.end());

        long long area_intersection = 0;
        for (size_t idx = 0; idx + 1 < xs.size(); ++idx) {
            long long xa = xs[idx], xb = xs[idx+1];
            if (xb <= xa) continue;
            double mid = (xa + xb) / 2.0;
            if (!(mid > xmin_rect && mid < xmax_rect)) continue; // only slabs within curtain x-range

            vector<long long> ys;
            ys.reserve(horiz.size());
            for (auto &H : horiz) {
                if ((double)H.x1 < mid && mid < (double)H.x2) {
