                long long yhigh = ys[t+1];
                long long lower = max(ylow, ymin_rect);
                long long upper = min(yhigh, ymax_rect);
                if (upper > lower) L += (upper - lower);
            }
            area_intersection += L * (xb - xa);
        }

        long long not_covered = area_window - area_intersection;
        cout << not_covered << "\n";
    }
