    int diff = depth[a] - depth[b];
    for(int i=0;i<LOG;i++) if(diff & (1<<i)) a = up[i][a];
    if(a == b) return a;
    for(int i=LOG-1;i>=0; --i){
        if(up[i][a] != up[i][b]){ a = up[i][a]; b = up[i][b]; }
    }
    return up[0][a];
}

int next_on_path(int u, int w){
    int g = lca(u,w);
    if(g != u){
        // path goes up from u towards g
        return up[0][u];
    } else {
        // path goes down from u to w; find the child of u on path to w
        int dist = depth[w] - depth[u];
        int node = w;
        int steps = dist - 1; // move up steps to reach the child of u
        for(int i=0;i<LOG;i++) if(steps & (1<<i)) node = up[i][node];
        return node;
    }
