        ans[e] = bestC;
        cnt[u][bestC]++;
        cnt[v][bestC]++;
    }

    long long total = 0;
    for(int i = 0; i < N; ++i){
        for(int c = 0; c < t; ++c){
            long long x = cnt[i][c];
            total += x * x;
        }
    }

    cout << total << "\n";
    for(int i = 0; i < k; ++i){
        cout << (ans[i] + 1);
        if(i + 1 < k) cout << ' ';
    }
    cout << "\n";

    return 0;
}
