  if(!(cin >> n >> m)) return 0;
  vector<pair<long long,long long>> pts(n);
  vector<long long> ys;
  ys.reserve(n);
  for(int i = 0; i < n; ++i){
    long long x, y; cin >> x >> y; pts[i] = {x, y}; ys.push_back(y);
  }

  // compress y-coordinates of treasures
  vector<long long> uniqY = ys;
  sort(uniqY.begin(), uniqY.end());
  uniqY.erase(unique(uniqY.begin(), uniqY.end()), uniqY.end());
  int ny = (int)uniqY.size();

  // map treasures to (x, yIndex)
  vector<pair<long long,int>> points(n);
  for(int i = 0; i < n; ++i){
    long long x = pts[i].first;
    long long y = pts[i].second;
    int idx = (int)(lower_bound(uniqY.begin(), uniqY.end(), y) - uniqY.begin());
    points[i] = {x, idx};
  }
  sort(points.begin(), points.end(), [](const auto &a, const auto &b){ return a.first < b.first; });

  struct Rect { long long x1,y1,x2,y2; int l, r; };
  vector<Rect> rects(m);
  for(int i = 0; i < m; ++i){
