    rects[i].x1 = x1; rects[i].y1 = y1; rects[i].x2 = x2; rects[i].y2 = y2;
    int l = (int)(lower_bound(uniqY.begin(), uniqY.end(), y1) - uniqY.begin());
    int r = (int)(upper_bound(uniqY.begin(), uniqY.end(), y2) - uniqY.begin()) - 1;
    rects[i].l = l; rects[i].r = r;
  }

  vector<Event> ev; ev.reserve(2*m);
  for(int i = 0; i < m; ++i){
    int l = rects[i].l, r = rects[i].r;
    if(l > r) continue; // empty y-range w.r.t treasures -> contributes 0
    ev.push_back({rects[i].x2, i, +1, l, r});
    long long xlow = rects[i].x1 - 1; // for x <= x1-1
    ev.push_back({xlow, i, -1, l, r});
  }
  sort(ev.begin(), ev.end(), [](const Event &a, const Event &b){
    if(a.x != b.x) return a.x < b.x;
    return a.id < b.id;
  });

  vector<long long> ans(m, 0);
  vector<int> bit(ny+2, 0);
  auto bit_add = [&](int idx0, int delta){
    int idx = idx0 + 1;
    while(idx <= ny){ bit[idx] += delta; idx += idx & -idx; }
  };
  auto bit_sum = [&](int idx0){
    int idx = idx0 + 1; long long s = 0;
    while(idx > 0){ s += bit[idx]; idx -= idx & -idx; }
    return s;
  };
  auto range_sum = [&](int l0, int r0){
    if(l0 > r0) return 0LL;
    return bit_sum(r0) - (l0 ? bit_sum(l0 - 1) : 0LL);
  };

  int idxPt = 0;
  for(const auto &e : ev){
    while(idxPt < n && points[idxPt].first <= e.x){
      bit_add(points[idxPt].second, 1);
      ++idxPt;
    }
    long long cur = range_sum(e.l, e.r);
    ans[e.id] += (long long)e.sign * cur;
  }

  for(int i = 0; i < m; ++i){
    cout << ans[i] << "\n";
  }
  return 0;
}
