#include <bits/stdc++.h>
using namespace std;

struct SegTree{
  int n;
  vector<pair<int,int>> st;
  SegTree() : n(0) {}
  SegTree(int n): n(n){ st.assign(4*n, make_pair(-1000000000, -1)); }
  void update(int idx, pair<int,int> val, int p, int l, int r){
    if(l==r){ st[p] = val; return; }
    int m=(l+r)/2;
    if(idx<=m) update(idx, val, 2*p, l, m);
    else update(idx, val, 2*p+1, m+1, r);
    st[p] = max(st[2*p], st[2*p+1]);
  }
  void update(int idx, pair<int,int> val){ update(idx, val, 1, 0, n-1); }
  pair<int,int> query(int ql, int qr, int p, int l, int r){
    if(ql>r || qr<l) return make_pair(-1000000000, -1);
    if(ql<=l && r<=qr) return st[p];
    int m=(l+r)/2;
    return max(query(ql, qr, 2*p, l, m), query(ql, qr, 2*p+1, m+1, r));
  }
  pair<int,int> query(int l, int r){ if(l>r) return make_pair(-1000000000, -1); return query(l, r, 1, 0, n-1); }
};

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N,Q;
  while (cin>>N>>Q){
    if(N==0 && Q==0) break;
    vector<vector<int>> g(N+1);
    vector<int> parent(N+1, 0);
    parent[1]=0;
    for(int i=2;i<=N;i++){ int p; cin>>p; parent[i]=p; g[p].push_back(i); }
    vector<int> depth(N+1,0), heavy(N+1, -1), sz(N+1,0);
    function<int(int)> dfs = [&](int u){
      sz[u] = 1;
      int maxsz = 0;
      for(int v: g[u]){
        depth[v] = depth[u] + 1;
        int s = dfs(v);
        sz[u] += s;
        if(s > maxsz){ maxsz = s; heavy[u] = v; }
      }
      return sz[u];
    };
    depth[1]=0; dfs(1);
    vector<int> head(N+1,0), pos(N+1,0);
    int curPos=0;
    function<void(int,int)> decompose = [&](int u, int h){
      head[u] = h; pos[u] = curPos++;
      if(heavy[u] != -1){
        decompose(heavy[u], h);
        for(int v: g[u]){
          if(v==heavy[u]) continue;
          decompose(v, v);
        }
      }
    };
    decompose(1,1);
    SegTree seg(N);
    seg.update(pos[1], {depth[1], 1});
    long long ans = 0;
    for(int i=0;i<Q;i++){
      char type; int v; cin>>type>>v;
      if(type=='M'){
        seg.update(pos[v], {depth[v], v});
      } else if(type=='Q'){
        pair<int,int> best = make_pair(-1000000000, -1);
        int u = v;
        while(head[u] != head[1]){
          best = max(best, seg.query(pos[head[u]], pos[u]));
          u = parent[head[u]];
        }
        best = max(best, seg.query(pos[1], pos[u]));
        int node = best.second;
        if(node < 0) node = 1;
        ans += node;
      }
    }
    cout<<ans<<"\n";
  }
  return 0;
}
