    W = {}
    for line in lines:
        a,b,c = map(int, line.strip().split())
        W[(a,b)] = c
    return W

# Build adjacency with weights

def build_adj(n, edges, W):
    adj = [[] for _ in range(n+1)]
    for u,v in edges:
        w = W[(u,v)] if (u,v) in W else W[(v,u)]
        adj[u].append((v,w))
        adj[v].append((u,w))
    return adj

# Compute distance between two nodes along the tree (path sum)

def dist(i, j, adj):
    n = len(adj) - 1
    visited = [False]*(n+1)
    stack = [(i, 0)]
    while stack:
        u, acc = stack.pop()
        if u == j:
            return acc
        visited[u] = True
        for v, w in adj[u]:
            if not visited[v]:
                stack.append((v, acc + w))
    return None

# Check that all sums from 1..M appear

def check(n, edges):
    W = run_solution(n, edges)
    adj = build_adj(n, edges, W)
    M = (2*n*n)//9
    sums = set()
    for i in range(1, n+1):
        for j in range(i+1, n+1):
            sums.add(dist(i, j, adj))
    for x in range(1, M+1):
        if x not in sums:
            return False
    return True


def main():
