using namespace std;

long long n;
vector<long long> p;
long long forbidden_cnt;
long long forbidden_sum;

void dfs(int idx, long long cur_lcm, int depth){
    for (int i = idx; i < (int)p.size(); ++i){
        long long pi = p[i];
        long long g = std::gcd(cur_lcm, pi);
        __int128 tmp = (__int128)cur_lcm / g * pi;
        if (tmp > n) continue;
        long long L = (long long)tmp;
        long long mcnt = n / L;
        if (((depth + 1) & 1) == 1){
            forbidden_cnt += mcnt;
            __int128 sum_m = (__int128)L * mcnt * (mcnt + 1) / 2;
            forbidden_sum += (long long)sum_m;
        } else {
            forbidden_cnt -= mcnt;
            __int128 sum_m = (__int128)L * mcnt * (mcnt + 1) / 2;
            forbidden_sum -= (long long)sum_m;
        }
        dfs(i + 1, L, depth + 1);
    }
}

