        if (has1){ cout.setf(std::ios::fixed); cout << setprecision(10) << 0.0 << "\n"; continue; }

        // Remove pi that are multiples of a smaller kept value
        vector<long long> kept;
        for (auto val : p){ bool is_mul = false; for (auto q: kept){ if (val % q == 0){ is_mul = true; break; } } if (!is_mul) kept.push_back(val); }
        p.swap(kept);

        // Remove pi > n (no contributions within 1..n)
        vector<long long> tmp; for (auto x: p) if (x <= n) tmp.push_back(x); p.swap(tmp);

        forbidden_cnt = 0; forbidden_sum = 0;
        if (p.empty()){
            long long total_sum = ( (__int128)n * (n + 1) / 2 );
            long long allowed_count = n;
            long long allowed_sum = total_sum;
            double ans = (double)allowed_sum / (double)allowed_count;
