        dfs(0, 1, 0);

        long long total_sum = (long long)((__int128)n * (n + 1) / 2);
        long long total_count = n;
        long long allowed_count = total_count - forbidden_cnt;
        long long allowed_sum = total_sum - forbidden_sum;
        double ans = 0.0;
        if (allowed_count > 0) ans = (double)allowed_sum / (double)allowed_count;
        cout.setf(std::ios::fixed); cout << setprecision(10) << ans << "\n";
    }
    return 0;
}
