#include <bits/stdc++.h>
using namespace std;

// DSU (Disjoint Set Union) / Union-Find
struct DSU {
    int n; vector<int> p, r;
    DSU(int n=0){init(n);}    
    void init(int n_){ n = n_; p.resize(n); r.assign(n,0); iota(p.begin(), p.end(), 0);}    
    int find(int x){ return p[x]==x? x : p[x]=find(p[x]); }
    void unite(int a,int b){ a=find(a); b=find(b); if(a==b) return; if(r[a]<r[b]) swap(a,b); p[b]=a; if(r[a]==r[b]) r[a]++; }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N; int W, H;
    if(!(cin >> N >> W >> H)) return 0;
    vector<pair<int,int>> pts(N);
    for(int i=0;i<N;i++){ int x,y; cin>>x>>y; pts[i]={x,y}; }

    DSU dsu(N);
    // Map rows to list of (x, idx) and columns to list of (y, idx)
    unordered_map<int, vector<pair<int,int>>> byRow; byRow.reserve(N*2);
    unordered_map<int, vector<pair<int,int>>> byCol; byCol.reserve(N*2);

    for(int i=0;i<N;i++){
        int x = pts[i].first; int y = pts[i].second;
        byRow[y].push_back({x,i});
        byCol[x].push_back({y,i});
    }

    // For each row, connect consecutive slimes by x
    for(auto &kv: byRow){
        auto &vec = kv.second; sort(vec.begin(), vec.end());
        for(size_t i=1;i<vec.size();++i){ int a=vec[i-1].second, b=vec[i].second; dsu.unite(a,b);}    
    }
    // For each column, connect consecutive slimes by y
    for(auto &kv: byCol){
        auto &vec = kv.second; sort(vec.begin(), vec.end());
        for(size_t i=1;i<vec.size();++i){ int a=vec[i-1].second, b=vec[i].second; dsu.unite(a,b);}    
    }

    // Count components among slimes
    int comp = 0;
    unordered_set<int> seen; seen.reserve(N*2);
    for(int i=0;i<N;i++){
        int f = dsu.find(i);
        if(!seen.count(f)){ seen.insert(f); comp++; }
    }

    long long answer = (long long)N - comp; // baseline
    cout << answer << "\n";
    return 0;
}
