long long bfs_exact(int N, int W, int H, const vector<pair<int,int>>& initial){
    // If N is 1, already merged
    if(N <= 1) return 0;
    auto canon = [](vector<pair<int,int>> v){ sort(v.begin(), v.end()); string s; for(auto &p: v){ s += to_string(p.first) + "," + to_string(p.second) + ";"; } return s; };
    queue<pair<vector<pair<int,int>>, int>> q; unordered_set<string> vis;
    vector<pair<int,int>> start = initial; sort(start.begin(), start.end()); string ks = canon(start); vis.insert(ks); q.push({start, 0});
    auto find_by_coords = [](const vector<pair<int,int>>& vec, int x, int y){ for(int i=0;i<(int)vec.size(); ++i){ if(vec[i].first==x && vec[i].second==y) return i; } return -1; };
    int dx[4] = {1,-1,0,0}; int dy[4] = {0,0,1,-1};
    while(!q.empty()){
        auto cur = q.front().first; int dist = q.front().second; q.pop();
        if((int)cur.size() == 1) return dist;
        // Build a map for quick occupancy check
        // For each slime i, try 4 directions
        for(int i=0;i<(int)cur.size(); ++i){
            for(int d=0; d<4; ++d){ int x = cur[i].first, y = cur[i].second; int nx = x, ny = y; bool merged=false; vector<pair<int,int>> nxt = cur;
                while(true){ int tx = nx + dx[d], ty = ny + dy[d]; if(tx<1 || tx>W || ty<1 || ty>H){ // boundary reached; stop at boundary cell (nx,ny)
                        nxt[i] = {nx, ny}; break; }
                    // check if another slime occupies (tx,ty)
                    int occ = -1; for(int k=0;k<(int)nxt.size(); ++k){ if(k==i) continue; if(nxt[k].first==tx && nxt[k].second==ty){ occ = k; break; } }
                    if(occ != -1){ // merge with slime at occ by moving into its cell
                        // remove slime i
                        nxt.erase(nxt.begin()+i);
                        // done; already merged into position (tx,ty) which is where nxt[occ] currently is
                        merged = true;
                        break;
                    }else{
                        nx = tx; ny = ty; // keep sliding
                        continue;
                    }
                }
                if(merged){ // i-th slime merged into some other; nxt already adjusted
                    // normalize and push if new
                    sort(nxt.begin(), nxt.end()); string key = canon(nxt);
                    if(!vis.count(key)){ vis.insert(key); q.push({nxt, dist+1}); }
                }else{ // moved to boundary cell (nx, ny)
                    nxt[i] = {nx, ny}; sort(nxt.begin(), nxt.end()); string key = canon(nxt);
                    if(!vis.count(key)){ vis.insert(key); q.push({nxt, dist+1}); }
                }
            }
        }
    }
    return LLONG_MAX/4; // should not reach
}

