static long long baseline(int N, int W, int H, const vector<pair<int,int>>& pts){
    struct DSU { vector<int> p, r; DSU(int n=0){init(n);} void init(int n){ p.resize(n); r.assign(n,0); iota(p.begin(), p.end(), 0);} int find(int a){ return p[a]==a? a : p[a]=find(p[a]); } void unite(int a,int b){ a=find(a); b=find(b); if(a==b) return; if(r[a]<r[b]) swap(a,b); p[b]=a; if(r[a]==r[b]) r[a]++; } };
    DSU dsu(N);
    unordered_map<int, vector<pair<int,int>>> byRow; byRow.reserve(N*2);
    unordered_map<int, vector<pair<int,int>>> byCol; byCol.reserve(N*2);
    for(int i=0;i<N;i++){ int x=pts[i].first, y=pts[i].second; byRow[y].push_back({x,i}); byCol[x].push_back({y,i}); }
    for(auto &kv: byRow){ auto vec = kv.second; sort(vec.begin(), vec.end()); for(size_t i=1;i<vec.size(); ++i) dsu.unite(vec[i-1].second, vec[i].second); }
    for(auto &kv: byCol){ auto vec = kv.second; sort(vec.begin(), vec.end()); for(size_t i=1;i<vec.size(); ++i) dsu.unite(vec[i-1].second, vec[i].second); }
    unordered_set<int> seen; int comp=0; for(int i=0;i<N;++i){ int f = dsu.find(i); if(!seen.count(f)){ seen.insert(f); comp++; } }
    return (long long)N - comp;
}

static long long canon_key(const vector<pair<int,int>>& v){ string s; for(auto &p: v){ s += to_string(p.first); s.push_back(','); s += to_string(p.second); s.push_back(';'); } return s; }

static long long bfs_exact(int N, int W, int H, vector<pair<int,int>> initial){
    if(N <= 1) return 0;
    // BFS state: vector of positions (sorted canonical form)
    auto normalize = [](vector<pair<int,int>> st){ sort(st.begin(), st.end()); return st; };
    auto key_of = [&](const vector<pair<int,int>>& st){ return canon_key(st); };
    queue<pair<vector<pair<int,int>>, int>> q; unordered_set<string> vis;
    initial = normalize(initial); string start = key_of(initial); vis.insert(start); q.push({initial, 0});
    int dx[4] = {1,-1,0,0}; int dy[4] = {0,0,1,-1};
    while(!q.empty()){
        auto cur = q.front(); q.pop(); auto st = cur.first; int dist = cur.second;
        if((int)st.size() <= 1) return dist;
        int m = st.size();
        for(int i=0;i<m; ++i){
            for(int d=0; d<4; ++d){
                int x = st[i].first, y = st[i].second; int mx = x, my = y; bool merged=false; auto nxt = st;
                while(true){ int tx = mx + dx[d], ty = my + dy[d];
                    if(tx < 1 || tx > W || ty < 1 || ty > H){ // hit wall, stay at (mx,my)
                        nxt[i] = {mx, my}; break;
                    }
                    int occ = -1; for(int k=0;k<(int)nxt.size(); ++k){ if(k==i) continue; if(nxt[k].first==tx && nxt[k].second==ty){ occ = k; break; } }
                    if(occ != -1){ // merge with slime at occ
                        nxt.erase(nxt.begin()+i);
                        merged = true;
                        break;
                    } else { mx = tx; my = ty; }
                }
                if(merged){ // moved slime merged with another; nxt size reduced by 1
                    sort(nxt.begin(), nxt.end()); string key = key_of(nxt); if(!vis.count(key)){ vis.insert(key); q.push({nxt, dist+1}); }
                } else {
                    nxt[i] = {mx, my}; sort(nxt.begin(), nxt.end()); string key = key_of(nxt); if(!vis.count(key)){ vis.insert(key); q.push({nxt, dist+1}); }
                }
            }
        }
    }
    return LLONG_MAX/4; // should not reach
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, W, H; if(!(cin >> N >> W >> H)) return 0; vector<pair<int,int>> pts(N); for(int i=0;i<N;++i){ int x,y; cin>>x>>y; pts[i]={x,y}; }
    long long ans;
    if(N <= 8) ans = bfs_exact(N, W, H, pts); else ans = baseline(N, W, H, pts);
    cout << ans << "\n";
    return 0;
}
