#include <bits/stdc++.h>
using namespace std;

// Digit Tree - Centroid Decomposition solution with iterative traversals

static const int MAXN = 100000 + 5;
int n;
long long M;
vector<pair<int,int>> adj[MAXN]; // (to, digit)
bool usedC[MAXN];
int subSize[MAXN];
long long answer = 0;
vector<long long> pow10, invPow;

// Extended gcd based modular inverse (for non-prime modulus)
long long egcd(long long a, long long b, long long &x, long long &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    long long x1, y1;
    long long g = egcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

long long modinv(long long a, long long m) {
    long long x, y;
    long long g = egcd(a, m, x, y);
    if (g != 1) return -1; // inverse doesn't exist
    x %= m; if (x < 0) x += m;
    return x;
}

// Decomposition utilities
void decompose(int start) {
    // Iterative DFS from start to collect component nodes and parents
    vector<int> order;
    vector<int> par(n, -1);
    // Build tree rooted at start
    stack<int> st;
    st.push(start);
    par[start] = -2; // root sentinel
    while (!st.empty()) {
        int u = st.top(); st.pop();
        order.push_back(u);
        for (auto &e : adj[u]) {
            int v = e.first;
            if (usedC[v] || v == par[u]) continue;
            par[v] = u;
            st.push(v);
        }
    }
    // Compute sizes in reverse order
    for (int i = (int)order.size() - 1; i >= 0; --i) {
        int u = order[i];
        subSize[u] = 1;
        for (auto &e : adj[u]) {
            int v = e.first;
            if (usedC[v] || par[v] != u) continue;
            subSize[u] += subSize[v];
        }
    }
    int total = subSize[start];
    // Find centroid by walking towards a heavy child if any
    int centroid = start;
    bool moved = true;
    while (moved) {
        moved = false;
        for (auto &e : adj[centroid]) {
            int v = e.first;
            if (usedC[v] || par[v] != centroid) continue; // only children
            if (subSize[v] > total / 2) {
                centroid = v;
                moved = true;
                break;
            }
        }
    }

    // Process centroid
    usedC[centroid] = true; // mark as removed for subtrees processing

    // Prepare maps for cross-subtree counting
    unordered_map<long long, long long> count_up; // up-values from previously processed subtrees
    unordered_map<long long, long long> need_from_down; // preimages t = (-down) * invPow[len]

    // Helper struct for node info within a subtree
    struct NodeInfo { int depth; int down; int up; };

    // For each neighbor subtree of centroid
    for (auto &e : adj[centroid]) {
        int v = e.first;
        int w = e.second;
        if (usedC[v]) continue; // skip the centroid itself's removal component
        // Collect all nodes in this subtree iteratively
        vector<NodeInfo> vec;
        // Iterative DFS: stack elements (node, parent, depth, down, up)
        struct StackItem { int u, p, depth; int down, up; };
        stack<StackItem> s2;
        int depth1 = 1;
        int down1 = (w) % (int)M;
        int up1 = (w) % (int)M;
        s2.push({v, centroid, depth1, down1, up1});
        while (!s2.empty()) {
            auto it = s2.top(); s2.pop();
            vec.push_back({ it.depth, it.down, it.up });
            int uu = it.u;
            int pp = it.p;
            for (auto &ee : adj[uu]) {
                int to = ee.first; int ww = ee.second;
                if (usedC[to] || to == pp) continue;
                int nd = it.depth + 1;
                int nDown = ( (long long)it.down * 10 + ww ) % M;
                int nUp = ( (long long)ww * pow10[it.depth] + it.up ) % M;
                s2.push({ to, uu, nd, nDown, nUp });
            }
        }
        // Pairs with centroid itself are counted during collection
        // Now count cross-subtree contributions with previously collected data
        // Contribution A: (u in previous subtrees, v in current subtree)
        for (auto &nd : vec) {
            long long t = ( (M - nd.down) % M );
            t = (t * invPow[nd.depth]) % M;
            auto itc = count_up.find(t);
            if (itc != count_up.end()) answer += itc->second;
        }
        // Contribution B: (u in current subtree, v in previous subtrees)
        for (auto &nd : vec) {
            auto itp = need_from_down.find(nd.up);
            if (itp != need_from_down.end()) answer += itp->second;
        }
        // Update maps with nodes from this subtree for future subtrees
        for (auto &nd : vec) {
            count_up[ nd.up ]++;
            long long t = ( (M - nd.down) % M );
            t = (t * invPow[nd.depth]) % M;
            need_from_down[ t ]++;
        }
    }

    // Recurse on subtrees formed by removing centroid
    for (auto &e : adj[centroid]) {
        int v = e.first;
        if (!usedC[v]) decompose(v);
    }
}

