        for (auto &nd : vec){
            count_up[ nd.up ]++;
            long long t_v = ( (long long)nd.down * invPow[nd.depth] ) % M;
            need_from_down[ t_v ]++;
        }
    }

    // Recurse on subtrees created by removing centroid
    for (auto &ed : adj[c]){
        int v = ed.first;
        if (!usedC[v]) decompose(v);
    }
}

