static const long long MOD = 1000000007LL;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; long long D;
    if(!(cin >> n >> D)) return 0;
    vector<vector<int>> children(n+1);
    for(int i = 2; i <= n; ++i){
        int p; cin >> p;
        children[p].push_back(i);
    }

    // Postorder without recursion
    vector<int> order; order.reserve(n);
    vector<pair<int,int>> st; st.reserve(n*2);
    st.push_back({1,0});
    while(!st.empty()){
        auto [v, state] = st.back(); st.pop_back();
        if(state == 0){
            st.push_back({v,1});
            for(int c : children[v]) st.push_back({c,0});
        } else {
            order.push_back(v);
        }
    }

    int N = n; // degree of polynomial
    vector<vector<long long>> F(n+1, vector<long long>(N+1, 0)); // F[v][x] for x=0..N

    for(int v : order){
        F[v][0] = 0;
        for(int x = 1; x <= N; ++x){
            long long prod = 1;
            for(int c : children[v]){
                prod = (prod * F[c][x]) % MOD;
                if(prod == 0) break;
            }
            F[v][x] = (F[v][x-1] + prod) % MOD;
        }
    }

    long long ans;
    if(D <= N){
