    } else {
        // Lagrange interpolation on points (i, y[i]) for i=0..N where y[i] = F[root][i]
        vector<long long> y(N+1);
        for(int i=0; i<=N; ++i) y[i] = F[1][i];

        // Precompute factorials and inverse factorials
        vector<long long> fact(N+1), invfact(N+1);
        fact[0] = 1;
        for(int i=1;i<=N;++i) fact[i] = (fact[i-1] * i) % MOD;
        auto modexp = [&](long long a, long long e){ long long r=1%MOD; a%=MOD; while(e){ if(e&1) r=(r*a)%MOD; a=(a*a)%MOD; e>>=1; } return r; };
        invfact[N] = modexp(fact[N], MOD-2);
        for(int i=N-1; i>=0; --i) invfact[i] = (invfact[i+1] * (i+1)) % MOD;

        long long A = D % MOD; // x-value for interpolation
        vector<long long> prefix(N+2, 1), suffix(N+2, 1);
        // prefix[i] = prod_{j=0}^{i-1} (A - j)
        prefix[0] = 1;
        for(int i=1; i<=N+1; ++i){
            long long term = (A - (i-1)) % MOD; if(term < 0) term += MOD;
            prefix[i] = (prefix[i-1] * term) % MOD;
