        // suffix[i] = prod_{j=i+1}^{N} (A - j)
        suffix[N] = 1;
        for(int i=N-1; i>=0; --i){
            long long term = (A - (i+1)) % MOD; if(term < 0) term += MOD;
            suffix[i] = (suffix[i+1] * term) % MOD;
        }
        long long res = 0;
        for(int i=0; i<=N; ++i){
            long long numerator = (prefix[i] * suffix[i]) % MOD; // prod (A - j) for j != i
            long long li = numerator;
            li = (li * invfact[i]) % MOD;
            li = (li * invfact[N - i]) % MOD;
            if( ((N - i) & 1) ) li = (MOD - li) % MOD;
            res = (res + y[i] * li) % MOD;
        }
        ans = res;
    }

    cout << (ans % MOD + MOD) % MOD << "\n";
    return 0;
}
