      while(e){ if(e & 1) r = (r * a) % MOD; a = (a * a) % MOD; e >>= 1; }
      return r;
    };
    invfact[N] = modexp(fact[N], MOD-2);
    for(int i = N-1; i >= 0; --i) invfact[i] = (invfact[i+1] * (i+1)) % MOD;

