#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

long long modpow(long long a, long long e){
    long long r = 1 % MOD;
    a %= MOD;
    while(e){
        if(e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if(!(cin >> n >> k)) return 0;

    long long count_k = 0;
    vector<int> p(k+1);

    function<void(int)> dfs = [&](int idx){
        if(idx > k){
            // Check: exactly one cycle in the mapping p[1..k], and 1 is on that cycle
            int cycles = 0;
            bool includes1 = false;
            vector<char> vis(k+1, 0);
            for(int i = 1; i <= k && cycles <= 1; ++i){
                if(vis[i]) continue;
                int u = i;
                vector<int> path;
                while(vis[u] == 0){
                    vis[u] = 1; // visiting
                    path.push_back(u);
                    u = p[u];
                }
                if(vis[u] == 1){
                    cycles++;
                    // find position of the start of cycle in path
                    int pos = -1;
                    for(int t = 0; t < (int)path.size(); ++t){
                        if(path[t] == u){ pos = t; break; }
                    }
                    for(int t = pos; t < (int)path.size(); ++t){
                        if(path[t] == 1) includes1 = true;
                    }
                }
                for(int v : path) vis[v] = 2;
            }
            if(cycles == 1 && includes1){
                count_k++;
                if(count_k >= MOD) count_k %= MOD;
            }
            return;
        }
        for(int v = 1; v <= k; ++v){
            p[idx] = v;
            dfs(idx + 1);
        }
    };

    dfs(1);

    long long outside = n - k;
    long long ways_out = modpow(outside, outside);
    long long ans = (count_k % MOD) * ways_out % MOD;
    cout << ans << "\n";
    return 0;
}
