#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n=0): n(n), bit(n+1, 0) {}
    void init(int n_) { n = n_; bit.assign(n+1, 0); }
    void add(int idx, long long delta) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
    }
    long long sum(int idx) {
        long long res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin >> n)) return 0;
    vector<vector<int>> children(n);
    for(int i = 0; i < n; ++i){
        int k; cin >> k;
        children[i].resize(k);
        for(int j = 0; j < k; ++j){ int c; cin >> c; children[i][j] = c; }
    }
    // Euler tour to get tin/tout for each node
    vector<int> tin(n), tout(n);
    int timer = 0;
    // iterative DFS to avoid recursion depth issues
    vector<pair<int,int>> st; // (node, state) 0 = enter, 1 = exit
    st.emplace_back(0, 0);
    while(!st.empty()){
        auto [u, state] = st.back(); st.pop_back();
        if(state == 0){
            tin[u] = ++timer;
            st.emplace_back(u, 1); // exit
            // push children in reverse order to preserve given order
            for(int i = (int)children[u].size() - 1; i >= 0; --i){
                st.emplace_back(children[u][i], 0);
            }
        } else {
            tout[u] = timer;
        }
    }

    Fenwick ft(n+2);
    int q; cin >> q;
    for(int i = 0; i < q; ++i){
        int t; cin >> t;
        if(t == 0){
            int v; long long w; cin >> v >> w;
            int l = tin[v], r = tout[v];
            ft.add(l, w);
            if(r + 1 <= n) ft.add(r + 1, -w);
        } else if(t == 1){
            int u; cin >> u;
            long long ans = ft.sum(tin[u]);
            cout << ans << "\n";
        }
    }
    return 0;
}
