vector<ll> a;
vector<int> sz;
vector<char> removed;
ll totalSum = 0;
ll answer = 0;

struct Left { ll t, sum_left, sum_left_weighted; };
struct Right { ll s, sum_right, w_right; };

void dfs_size(int u, int p){
    sz[u] = 1;
    for(int v: g[u]) if(v != p && !removed[v]){
        dfs_size(v, u);
        sz[u] += sz[v];
    }
}
int dfs_centroid(int u, int p, int tot){
    for(int v: g[u]) if(v != p && !removed[v]){
        if(sz[v] > tot/2) return dfs_centroid(v, u, tot);
    }
    return u;
}

void dfs_collect(int u, int p, int depth, ll sum_from_c, ll Sr, ll wRight, int centroid, vector<Left>& lefts, vector<Right>& rights){
    Left L{ (ll)depth, sum_from_c, depth * sum_from_c - Sr };
    lefts.push_back(L);
    Right R{ (ll)depth, sum_from_c - a[centroid], wRight };
    rights.push_back(R);
    for(int v: g[u]) if(v != p && !removed[v]){
        dfs_collect(v, u, depth+1, sum_from_c + a[v], Sr + (depth+1) * a[v], wRight + depth * a[v], centroid, lefts, rights);
    }
}

void decompose(int entry);

void decompose(int entry){
    dfs_size(entry, -1);
    int c = dfs_centroid(entry, -1, sz[entry]);
    removed[c] = 1;

    // Li Chao hull over x = sum_left, domain [0, totalSum]
    LiChao hull(0, max(1LL, totalSum)); // ensure non-empty domain
    hull.clear();
    hull.add_line(Line(0, 0)); // y = 0 corresponds to s = 0, y = 0

    vector<int> neigh;
    for(int v: g[c]) if(!removed[v]) neigh.push_back(v);

    auto process_subtree = [&](int start){
        vector<Left> lefts; vector<Right> rights;
        dfs_collect(start, c, 1, a[c] + a[start], a[start], 0, c, lefts, rights);
        // query for lefts
        for(auto &L : lefts){
            ll LeftBase = L.t * L.sum_left - L.sum_left_weighted + L.sum_left;
            ll val = LeftBase + hull.query(L.sum_left);
            if(val > answer) answer = val;
        }
        // insert rights as lines
        for(auto &R : rights){
            hull.add_line(Line(R.s, R.s * R.sum_right - R.w_right));
        }
    };

    // first pass (forward)
    for(int nb : neigh) process_subtree(nb);
    // second pass (reverse) to cover opposite orientation
    for(int i = (int)neigh.size()-1; i>=0; --i) process_subtree(neigh[i]);

    // recurse on subtrees
    for(int nb: neigh) decompose(nb);
}

