#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll NEG_INF = -(1LL<<62);

struct Line {
    ll m, b; // y = m*x + b
    Line(ll _m=0, ll _b=NEG_INF): m(_m), b(_b) {}
    inline ll value(ll x) const { return m*x + b; }
};

// Dynamic Li Chao Tree for maximum queries on integer domain [minX, maxX]
struct LiChao {
    struct Node {
        Line ln;
        Node* l;
        Node* r;
        Node(Line _ln): ln(_ln), l(nullptr), r(nullptr) {}
    };
    Node* root;
    ll minX, maxX;
    LiChao(ll _minX=0, ll _maxX=0): root(nullptr), minX(_minX), maxX(_maxX) {}
    void clear() { root = nullptr; }
    void add_line(Line nw) { add_line(nw, root, minX, maxX); }
    void add_line(Line nw, Node* &node, ll l, ll r) {
        if (!node) { node = new Node(nw); return; }
        ll mid = (l + r) >> 1;
        bool lef = nw.value(l) > node->ln.value(l);
        bool midb = nw.value(mid) > node->ln.value(mid);
        if (midb) swap(node->ln, nw);
        if (l == r) return;
        if (lef != midb) add_line(nw, node->l, l, mid);
        else add_line(nw, node->r, mid+1, r);
    }
    ll query(ll x) { return query(x, root, minX, maxX); }
    ll query(ll x, Node* node, ll l, ll r) {
        if (!node) return NEG_INF;
        ll res = node->ln.value(x);
        if (l == r) return res;
        ll mid = (l + r) >> 1;
        if (x <= mid) return max(res, query(x, node->l, l, mid));
        else return max(res, query(x, node->r, mid+1, r));
    }
};

