// Collect data for a subtree rooted at 'start' (child of centroid 'c')
void dfs_collect(int u, int p, int depth, ll pathSum, ll sumJ, ll sumRight, ll wRight, int centroid, vector<Left>& lefts, vector<Right>& rights){
    // Left data for endpoint p=u: depth = distance from centroid to u
    lefts.push_back({ depth, pathSum, sumJ });
    rights.push_back({ depth, sumRight, wRight });
    for(int v: g[u]) if(v != p && !removed[v]){
        dfs_collect(v, u, depth+1, pathSum + a[v], sumJ + (ll)(depth+1) * a[v], sumRight + a[v], wRight + (ll)(depth+1) * a[v], centroid, lefts, rights);
    }
}

void decompose(int entry){
    dfs_size(entry, -1);
    int c = dfs_centroid(entry, -1, sz[entry]);
    removed[c] = 1;

    // Gather neighboring subtrees of centroid
    vector<int> neigh;
    for(int v: g[c]) if(!removed[v]) neigh.push_back(v);

    // Initialize Li Chao hull (domain of x is pathSum, which can be up to totalSum)
    LiChao hull(0, max(1LL, totalSum));
    hull.clear();
    // We will accumulate rights from subtrees, and after each subtree, insert its rights as lines.

    // Forward pass: process subtrees in order
    for(int nb : neigh){
        vector<Left> lefts; vector<Right> rights;
        dfs_collect(nb, c, 1, a[c] + a[nb], a[nb], a[nb], a[nb], c, lefts, rights);
        // 1) Paths with p=c and q in this subtree: update answer directly for each right endpoint
        for(auto &R : rights){
            ll cand = (R.depth + 1LL) * (a[c] + R.sumRight) - R.wRight; // (R+1)*(a[c]+sumRight) - wRight
            if(cand > answer) answer = cand;
        }
        // 2) Cross-subtree paths where p is in the current left subtree
        for(auto &L : lefts){
            ll val = L.pathSum + L.sumJ + hull.query(L.pathSum);
            if(val > answer) answer = val;
        }
        // 3) Add rights of this subtree to the hull for future subtrees
        for(auto &R : rights){
            hull.add_line(Line(R.depth, (R.depth + 1LL) * R.sumRight - R.wRight));
        }
    }

    // Reverse pass: handle opposite orientation of subtrees
    hull.clear();
    for(int idx = (int)neigh.size()-1; idx >= 0; --idx){
        int nb = neigh[idx];
        vector<Left> lefts; vector<Right> rights;
        dfs_collect(nb, c, 1, a[c] + a[nb], a[nb], a[nb], a[nb], c, lefts, rights);
        // 1) p=c contributions in this reversed order
        for(auto &R : rights){
            ll cand = (R.depth + 1LL) * (a[c] + R.sumRight) - R.wRight;
            if(cand > answer) answer = cand;
        }
        // 2) cross-subtree with left in this subtree
        for(auto &L : lefts){
            ll val = L.pathSum + L.sumJ + hull.query(L.pathSum);
            if(val > answer) answer = val;
        }
        // 3) insert rights into hull for future iterations
        for(auto &R : rights){
            hull.add_line(Line(R.depth, (R.depth + 1LL) * R.sumRight - R.wRight));
        }
    }

    // Recurse into each subtree
    for(int nb : neigh) decompose(nb);
}

