    for(int i=0;i<n;i++){ ll x; cin >> x; a[i] = x; totalSum += x; mx = max(mx, x); }
    // Initial answer could be a single node path
    answer = mx;

    sz.assign(n, 0);
    removed.assign(n, 0);
    decompose(0);
    cout << answer << "\n";
    return 0;
}
