using namespace std;

// Feasibility check for a given m
bool feasible(int n, int k, const string& s, int m){
    if(m == 0) return true;
    vector<vector<int>> good(k);
    for(int i = 0; i < k; ++i){
        char c = 'a' + i;
        int bad = 0;
        for(int j = 0; j < m && j < n; ++j) if(s[j] != c && s[j] != '?') bad++;
        if(m <= n && bad == 0) good[i].push_back(0);
        for(int l = 1; l + m <= n; ++l){
            int rem = l - 1, add = l + m - 1;
            if(s[rem] != c && s[rem] != '?') bad--;
            if(s[add] != c && s[add] != '?') bad++;
            if(bad == 0) good[i].push_back(l);
        }
    }
    int full = 1 << k; const int INF = n + 5;
    vector<int> dp(full, INF);
    dp[0] = 0;
    for(int mask = 0; mask < full; ++mask){
        if(dp[mask] > n) continue;
        for(int i = 0; i < k; ++i) if(!(mask & (1 << i)){
