#include <bits/stdc++.h>
using namespace std;

static inline long long K(long long x, long long y){
    // Pack coordinates into a 64-bit key with a safe offset to avoid negatives
    unsigned long long ux = (unsigned long long)(x + 1000000LL);
    unsigned long long uy = (unsigned long long)(y + 1000000LL);
    unsigned long long res = (ux << 32) ^ uy;
    return (long long)res;
}

struct State {
    int vx, vy, sx, sy;
    bool operator==(State const& o) const {
        return vx==o.vx && vy==o.vy && sx==o.sx && sy==o.sy;
    }
};

struct StateHash {
    size_t operator()(State const& s) const noexcept {
        size_t h = std::hash<int>()(s.vx);
        h = h*1315423911u + std::hash<int>()(s.vy);
        h = h*1315423911u + std::hash<int>()(s.sx);
        h = h*1315423911u + std::hash<int>()(s.sy);
        return h;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long vx, vy, sx, sy;
    int m;
    if(!(cin >> vx >> vy >> sx >> sy >> m)) return 0;

    unordered_set<long long> tree;
    tree.reserve(m*2+10);
    for(int i=0;i<m;i++){
        long long tx, ty;
        cin >> tx >> ty;
        tree.insert(K(tx, ty));
    }
    auto isTree = [&](long long x, long long y)->bool {
        return tree.find(K(x,y)) != tree.end();
    };

    string path;
    const int MAX_STEPS = 1000000;
    unordered_set<State, StateHash> seen;
    seen.reserve(100000);
    State init{(int)vx,(int)vy,(int)sx,(int)sy};
    seen.insert(init);

    int step = 0;
    // Moves: L, R, U, D
    const int dx[4] = {-1, 1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};
    const char dc[4] = {'L','R','U','D'};

    while(true){
        if (vx == sx && vy == sy){
            cout << path;
            return 0;
        }
        if (step >= MAX_STEPS){
            cout << "-1";
            return 0;
        }
        int curDist = (int)( llabs(sx - vx) + llabs(sy - vy) );
        bool anyMove = false;
        int bestIdx = -1;
        int bestVx=0, bestVy=0, bestSx=0, bestSy=0;
        int bestDelta = INT_MAX;
        for(int i=0;i<4;i++){
            long long nvx = (long long)vx + dx[i];
            long long nvy = (long long)vy + dy[i];
            if (isTree(nvx, nvy)) continue; // can't move there

            long long nsx = sx;
            long long nsy = sy;
            long long tnx = sx + dx[i];
            long long tny = sy + dy[i];
            if (!isTree(tnx, tny)){
                nsx = tnx; nsy = tny;
            }
            int ndist = (int)( llabs(nsx - nvx) + llabs(nsy - nvy) );
            int delta = ndist - curDist;
            if (bestIdx == -1 || delta < bestDelta){
                bestIdx = i;
                bestDelta = delta;
                bestVx = (int)nvx; bestVy = (int)nvy;
                bestSx = (int)nsx; bestSy = (int)nsy;
                anyMove = true;
            }
        }
        if (!anyMove){
            cout << "-1";
            return 0;
        }
        // apply best move
        path.push_back(dc[bestIdx]);
        vx = bestVx; vy = bestVy; sx = bestSx; sy = bestSy;
        step++;
        if (vx == sx && vy == sy){
            cout << path;
            return 0;
        }
        State st{(int)vx,(int)vy,(int)sx,(int)sy};
        if (seen.find(st) != seen.end()){
            cout << "-1";
            return 0;
        }
        seen.insert(st);
    }
}
