using namespace std;

static inline long long pack(int x, int y) {
    // Pack coordinates into a 64-bit key for the obstacle set; offset to handle negatives
    const long long OFF = 1000LL; // safe offset given input bounds
    unsigned long long ux = (unsigned long long)(x + OFF);
    unsigned long long uy = (unsigned long long)(y + OFF);
    return (ux << 32) ^ uy;
}

struct State {
    int vx, vy, sx, sy;
    bool operator==(State const& o) const {
