    size_t operator()(State const& s) const noexcept {
        size_t h = std::hash<int>()(s.vx);
        h = h*1315423911u + std::hash<int>()(s.vy);
        h = h*1315423911u + std::hash<int>()(s.sx);
        h = h*1315423911u + std::hash<int>()(s.sy);
        return h;
    }
};

