    const int dy[4] = {0, 0, 1, -1};
    const char dc[4] = {'L','R','U','D'};

    // BFS structures
    struct Node { int vx, vy, sx, sy; int parent; char move; };
    vector<Node> nodes;
    nodes.reserve(100000);
