    nodes.push_back({(int)vx0, (int)vy0, (int)sx0, (int)sy0, -1, 0});
    queue<int> q; q.push(0);
    unordered_set<State, StateHash> vis;
    vis.reserve(100000);
    vis.insert({(int)vx0, (int)vy0, (int)sx0, (int)sy0});

    while(!q.empty()){
        int idx = q.front(); q.pop();
        const Node &cur = nodes[idx];
        if (cur.vx == cur.sx && cur.vy == cur.sy){
            // reconstruct path
            string path;
            for(int p = idx; p != 0; p = nodes[p].parent){
                path.push_back(nodes[p].move);
            }
            reverse(path.begin(), path.end());
            cout << path;
            return 0;
        }
        for(int dir=0; dir<4; ++dir){
            int nvx = cur.vx + dx[dir];
            int nvy = cur.vy + dy[dir];
            if (isTree(nvx, nvy)) continue;
            int nsx = cur.sx, nsy = cur.sy;
            int tnx = cur.sx + dx[dir];
            int tny = cur.sy + dy[dir];
            if (!isTree(tnx, tny)) { nsx = tnx; nsy = tny; }
            if (!inBound(nvx, nvy) || !inBound(nsx, nsy)) continue;
            State ns{nvx, nvy, nsx, nsy};
            if (vis.find(ns) != vis.end()) continue;
            vis.insert(ns);
            nodes.push_back({nvx, nvy, nsx, nsy, idx, dc[dir]});
            q.push((int)nodes.size()-1);
        }
    }

    cout << -1;
    return 0;
}
