// Segment Tree for max with associated node id
struct SegTree {
    int n; // 0..n inclusive depths
    const int NEG = -1000000000;
    vector<pair<int,int>> st; // (val, id)
    SegTree() : n(0) {}
    SegTree(int _n) { init(_n); }
    void init(int _n) {
        n = _n;
        st.assign(4*(n+5), make_pair(NEG, -1));
    }
    void update(int p, int val, int id, int idx, int l, int r) {
        if (l == r) {
            if (val > st[idx].first) st[idx] = {val, id};
            return;
        }
        int mid = (l + r) >> 1;
        if (p <= mid) update(p, val, id, idx<<1, l, mid);
        else update(p, val, id, idx<<1|1, mid+1, r);
        st[idx] = max(st[idx<<1], st[idx<<1|1]);
    }
    void update(int p, int val, int id) {
        if (p < 0 || p > n) return;
        update(p, val, id, 1, 0, n);
    }
    pair<int,int> query(int ql, int qr, int idx, int l, int r) {
        if (qr < l || r < ql) return {NEG, -1};
        if (ql <= l && r <= qr) return st[idx];
        int mid = (l + r) >> 1;
        auto a = query(ql, qr, idx<<1, l, mid);
        auto b = query(ql, qr, idx<<1|1, mid+1, r);
        return max(a, b);
    }
    pair<int,int> query(int lq, int rq) {
        if (lq > rq) return {NEG, -1};
        return query(lq, rq, 1, 0, n);
    }
};

struct NodeInfo { int depth; int sum; int id; };
struct Subtree { vector<NodeInfo> vec; int max_depth; };

