        if (v == p || removed[v]) continue;
        sz[u] += dfs_size(v, u);
    }
    return sz[u];
}
int dfs_centroid(int u, int p, int total) {
    for (auto &e : g[u]) {
        int v = e.to;
        if (v == p || removed[v]) continue;
        if (sz[v] > total/2) return dfs_centroid(v, u, total);
    }
    return u;
}

