#include <bits/stdc++.h>
using namespace std;
using ll = long long;

static ll gcdll(ll a, ll b){ if(b==0) return llabs(a); return gcdll(b, a%b); }

static pair<ll,ll> normalize(ll num, ll den){
    if(den < 0){ num = -num; den = -den; }
    ll g = gcdll(llabs(num), llabs(den));
    if(g) { num /= g; den /= g; }
    return {num, den};
}

struct PairHash {
    size_t operator()(const pair<ll,ll>& p) const noexcept {
        return std::hash<long long>()((p.first) ^ (p.second << 1));
    }
};

// Edmonds' Blossom algorithm (robust template)
class Blossom {
public:
    int n; vector<vector<int>> g; vector<int> match, p, base; vector<char> used, blossom; vector<int> q;
    Blossom(int n=0): n(n), g(n) {}
    void addEdge(int u, int v){ if(u==v) return; g[u].push_back(v); g[v].push_back(u); }

    int lca(int a, int b){
        vector<char> usedLocal(n,false);
        while(true){
            a = base[a];
            usedLocal[a] = true;
            if(match[a] == -1) break;
            a = p[match[a]];
        }
        while(true){
            b = base[b];
            if(usedLocal[b]) return b;
            b = p[match[b]];
        }
    }

    void markPath(int v, int b, int children){
        while(base[v] != b){
            blossom[base[v]] = blossom[base[match[v]]] = true;
            p[v] = children;
            children = match[v];
            v = p[match[v]];
        }
    }

    int findPath(int root){
        used.assign(n, 0);
        p.assign(n, -1);
        base.resize(n); iota(base.begin(), base.end(), 0);
        q.clear(); q.reserve(n);
        q.push_back(root); int qi=0; used[root] = 1;
        while(qi < (int)q.size()){
            int v = q[qi++];
            for(int u : g[v]){
                if(base[v] == base[u] || match[v] == u) continue;
                if(u == root || (match[u] != -1 && p[match[u]] != -1)){
                    int curbase = lca(v, u);
                    blossom.assign(n, 0);
                    markPath(v, curbase, u);
                    markPath(u, curbase, v);
                    for(int i=0;i<n;i++){
                        if(blossom[base[i]]){
                            base[i] = curbase;
                            if(!used[i]){ used[i] = 1; q.push_back(i); }
                        }
                    }
                } else if(p[u] == -1){
                    p[u] = v;
                    if(match[u] == -1){
                        int x = u;
                        while(x != -1){
                            int pv = p[x]; int pp = (pv==-1 ? -1 : match[pv]);
                            match[x] = pv; if(pv != -1) match[pv] = x; x = pp;
                        }
                        return 1;
                    } else {
                        int w = match[u];
                        if(!used[w]){ used[w] = 1; q.push_back(w); }
                    }
                }
            }
        }
        return 0;
    }

    int maxMatching(){
        match.assign(n, -1); p.assign(n, -1); base.resize(n); used.assign(n, 0); blossom.assign(n, 0);
        int res = 0;
        for(int i=0;i<n;i++) if(match[i] == -1) res += findPath(i);
        return res;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin>>n)) return 0;
    vector<ll> A(n), B(n), C(n), D(n);
    for(int i=0;i<n;i++){
        ll a,b,c,d; cin>>a>>b>>c>>d; A[i]=a; B[i]=b; C[i]=c; D[i]=d; }

    unordered_map<pair<ll,ll>, vector<int>, PairHash> mp; mp.reserve(n*2); mp.max_load_factor(0.7);

    auto addSlope = [&](int idx, const pair<ll,ll>& key){ mp[key].push_back(idx); };

    for(int i=0;i<n;i++){
        __int128 n1 = ( (__int128) C[i] * B[i] );
        __int128 d1 = ( (__int128) D[i] * (A[i] + B[i]) );
        auto s1 = normalize((long long)n1, (long long)d1);
        addSlope(i, s1);

        __int128 n2 = ( (__int128) (C[i] + D[i]) * B[i] );
        __int128 d2 = ( (__int128) D[i] * A[i] );
        auto s2 = normalize((long long)n2, (long long)d2);
        addSlope(i, s2);
    }

    vector<vector<int>> adj(n);
    for(auto &kv : mp){
        auto vec = kv.second; sort(vec.begin(), vec.end()); vec.erase(unique(vec.begin(), vec.end()), vec.end());
        for(size_t i=0;i<vec.size();++i) for(size_t j=i+1;j<vec.size();++j){ int u=vec[i], v=vec[j]; adj[u].push_back(v); adj[v].push_back(u); }
    }
    for(int i=0;i<n;i++){ sort(adj[i].begin(), adj[i].end()); adj[i].erase(unique(adj[i].begin(), adj[i].end()), adj[i].end()); }

    Blossom bl(n);
    for(int u=0; u<n; ++u){ for(int v: adj[u]) if(u < v) bl.addEdge(u, v); }

    int m = bl.maxMatching();
    vector<pair<int,int>> moves; for(int i=0;i<n;i++) if(bl.match[i] != -1 && i < bl.match[i]) moves.emplace_back(i+1, bl.match[i]+1);
    cout << moves.size() << "\n";
    for(auto &pr: moves) cout << pr.first << " " << pr.second << "\n";
    return 0;
}
