#include <bits/stdc++.h>
using namespace std;

struct SegTree {
    int n;
    vector<int> st;
    function<int(int,int)> lca;
    SegTree(int n, function<int(int,int)> lcaF): n(n), lca(lcaF) {
        st.assign(4*n+4,0);
    }
    void build(int p,int l,int r){
        if(l==r){
            st[p] = l;
            return;
        }
        int m=(l+r)/2;
        build(p*2,l,m);
        build(p*2+1,m+1,r);
        st[p] = lca(st[p*2], st[p*2+1]);
    }
    int query(int p,int l,int r,int i,int j){
        if(i>r || j<l) return 0;
        if(i<=l && r<=j) return st[p];
        int m=(l+r)/2;
        int a = query(p*2,l,m,i,j);
        int b = query(p*2+1,m+1,r,i,j);
        return lca(a,b);
    }
    void init_build(){
        build(1,1,n);
    }
    int rangeLCA(int L,int R){
        if(L>R) return 0;
        return query(1,1,n,L,R);
    }
};

