int dfsSize(int u, int p){
    subSize[u] = 1;
    for(auto &e: g[u]) if (e.to != p && !removed[e.to]) subSize[u] += dfsSize(e.to, u);
    return subSize[u];
}

int dfsCentroid(int u, int p, int tot){
    for(auto &e: g[u]) if (e.to != p && !removed[e.to]){
        if (subSize[e.to] > tot/2) return dfsCentroid(e.to, u, tot);
    }
    return u;
}

struct SubtreeData {
    int root;
    long long maxA;
    vector<pair<long long,long long>> needs; // (need_y, delta_y)
};

void dfsCollect(int u, int p, long long ce, long long w_parent, long long need_parent, long long delta_parent, int centroid, long long w_centroid, long long &ma
xA_sub, vector<pair<long long,long long>> &needs_sub){
    long long w_p = w_parent;
    long long need_u = max( ce, need_parent + ce - w_p );
    long long delta_u = - ce + w_p + delta_parent;

    // Feasibility for A_u: path from u to centroid ends at centroid
    if (W[u] >= ce && (W[u] - ce + w_p) >= need_parent){
        long long A_u = (W[u] - ce + w_p) + delta_parent;
        if (A_u > maxA_sub) maxA_sub = A_u;
        if (A_u > ans) ans = A_u;
    }

    // Outward path data: centroid -> u
    needs_sub.push_back({need_u, delta_u});
    if (w_centroid >= need_u){
        long long cand = w_centroid + delta_u;
        if (cand > ans) ans = cand;
    }

    for(auto &e: g[u]) if (e.to != p && !removed[e.to]){
        dfsCollect(e.to, u, e.w, W[u], need_u, delta_u, centroid, w_centroid, maxA_sub, needs_sub);
    }
}

void processCentroid(int c){
    vector<SubtreeData> subs;
    for(auto &e: g[c]) if (!removed[e.to]){
        int root = e.to; long long ce = e.w;
        long long maxA_sub = LLONG_MIN/4;
        vector<pair<long long,long long>> needs_sub; needs_sub.clear();
        dfsCollect(root, c, ce, W[c], 0, 0, c, W[c], maxA_sub, needs_sub);
        SubtreeData sd; sd.root = root; sd.maxA = maxA_sub; sd.needs = move(needs_sub);
        subs.push_back(move(sd));
    }

    int m = (int)subs.size();
    if (m > 0){
        vector<long long> maxA_per_sub(m);
        for(int i=0;i<m;i++) maxA_per_sub[i] = subs[i].maxA;
        long long best1 = LLONG_MIN/4, best2 = LLONG_MIN/4; int idx1=-1, idx2=-1;
        for(int i=0;i<m;i++){
            long long v = maxA_per_sub[i];
            if (v > best1){ best2 = best1; idx2 = idx1; best1 = v; idx1 = i; }
            else if (v > best2){ best2 = v; }
        }
        for(int i=0;i<m;i++){
            long long M_excl = (i != idx1) ? best1 : best2;
            if (M_excl <= LLONG_MIN/8) continue;
