  vector<int> dp((size_t)M * (K + 1), NEG);
  auto IDX = [K](int mask, int f){ return (size_t)mask * (K + 1) + f; };

  dp[IDX(0, 0)] = 0;

  for(int mask = 0; mask < M; ++mask){
    int i = __builtin_popcount((unsigned)mask); // next person index
    if(i >= N) continue;
    for(int f = 0; f <= K; ++f){
      int cur = dp[IDX(mask, f)];
      if(cur == NEG) continue;
      for(int j = 0; j < N; ++j){
        if(((mask >> j) & 1) == 0){
          int nm = mask | (1 << j);
          if(f < K){
            int val = cur + F[i][j];
            int &to = dp[IDX(nm, f + 1)];
            if(val > to) to = val;
          }
          int val2 = cur + S[i][j];
          int &to2 = dp[IDX(nm, f)];
          if(val2 > to2) to2 = val2;
        }
      }
    }
  }

  cout << dp[IDX(M - 1, K)] << "\n";
  return 0;
}
