using namespace std;

static int Nglob;
static vector<int> parentArr;
static vector<long long> valueArr;

long double compute_E() {
  int N = Nglob;
  vector<vector<int>> children(N+1);
  for (int i = 2; i <= N; ++i) {
    int p = parentArr[i]; if (p >= 1 && p <= N) children[p].push_back(i);
  }
  // Postorder traversal to compute subtree sizes
  vector<int> post; post.reserve(N);
  vector<pair<int,int>> st; st.emplace_back(1,0);
  while(!st.empty()) {
    int v = st.back().first; int state = st.back().second; st.pop_back();
    if (state == 0) {
      st.emplace_back(v,1);
      for (auto it = children[v].rbegin(); it != children[v].rend(); ++it) st.emplace_back(*it,0);
    } else {
      post.push_back(v);
    }
  }
  vector<long long> sub(N+1,0), sumsq(N+1,0);
  for (int v : post) {
    long long s = 1, ss = 0;
    for (int c : children[v]) { s += sub[c]; ss += sub[c]*sub[c]; }
    sub[v] = s; sumsq[v] = ss;
  }
  __int128 total = 0;
  for (int v = 1; v <= N; ++v) {
    long long Nv = sub[v]*sub[v] - sumsq[v];
    total += (__int128)valueArr[v] * Nv;
  }
  long double denom = (long double)N * (long double)N;
  return (long double)total / denom;
}

bool is_subtree(int a, int b) {
  int N = Nglob;
  vector<vector<int>> children(N+1);
  for (int i = 2; i <= N; ++i) {
    int p = parentArr[i]; if (p>=1 && p<=N) children[p].push_back(i);
  }
  vector<int> tin(N+1,0), tout(N+1,0);
  int timer = 0; vector<pair<int,int>> st; st.emplace_back(1,0);
  while(!st.empty()) {
    int v = st.back().first; int stt = st.back().second; st.pop_back();
    if (stt == 0) {
      tin[v] = ++timer; st.emplace_back(v,1);
      for (auto it = children[v].rbegin(); it != children[v].rend(); ++it) st.emplace_back(*it,0);
    } else {
      tout[v] = timer;
    }
  }
  return (tin[a] <= tin[b] && tout[b] <= tout[a]);
}

