import random, subprocess
from itertools import permutations


def all_dist(n, edges):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        a -= 1; b -= 1
        adj[a].append(b); adj[b].append(a)
    dist = [[-1]*n for _ in range(n)]
    from collections import deque
    for s in range(n):
        q = deque([s]); dist[s][s] = 0
        while q:
            u = q.popleft()
            for w in adj[u]:
                if dist[s][w] == -1:
                    dist[s][w] = dist[s][u] + 1
                    q.append(w)
    return dist


def derangements(n):
    perm = [0]*n
    used = [False]*(n+1)
    res = []
    def dfs(pos):
        if pos == n:
            res.append(perm.copy())
            return
        for v in range(1, n+1):
            if not used[v] and v != pos+1:
                used[v] = True
                perm[pos] = v
                dfs(pos+1)
                used[v] = False
    dfs(0)
    return res


def brute_min(n, edges):
    dist = all_dist(n, edges)
    best = 10**9
    bestp = None
    for perm in derangements(n):
        total = sum(dist[i][perm[i]-1] for i in range(n))
        if total < best:
            best = total
            bestp = perm
    return best, bestp


def main():
    random.seed(0)
    failures = []
    for n in range(2, 8):
        for _ in range(5):
            edges = []
            for i in range(2, n+1):
