                edges.append((i, p))
            lines = [str(n)] + [f"{a} {b}" for a, b in edges]
            inp = "\n".join(lines) + "\n"
            proc = subprocess.run(["./village_min"], input=inp, text=True, capture_output=True)
            if proc.returncode != 0:
                print("Binary crashed on n=", n)
                print(proc.stderr)
                failures.append((n, edges, proc.stdout, proc.stderr))
                continue
            out = proc.stdout.strip().splitlines()
            if not out:
                print("No output for n=", n)
                failures.append((n, edges, proc.stdout, proc.stderr))
                continue
            # Validate first line is a number
            try:
                ans = int(out[0].split()[0])
            except Exception:
                print("Invalid answer line for n=", n, "output=", proc.stdout)
                failures.append((n, edges, proc.stdout, proc.stderr))
                continue
            # Validate permutation line presence
            if len(out) < 2:
                print("Missing permutation line for n=", n)
                failures.append((n, edges, proc.stdout, proc.stderr))
                continue
            perm = list(map(int, out[1].split()))
            if len(perm) != n:
                print("Invalid permutation length for n=", n, "perm=", perm)
                failures.append((n, edges, proc.stdout, proc.stderr))
                continue
            if any(x < 1 or x > n for x in perm) or len(set(perm)) != n:
                print("Invalid permutation values or duplicates for n=", n, "perm=", perm)
                failures.append((n, edges, proc.stdout, proc.stderr))
                continue
            # verify derangement
            if any(perm[i] == i+1 for i in range(n)):
                print("Not a derangement for n=", n, "perm=", perm)
                failures.append((n, edges, proc.stdout, proc.stderr))
                continue
            dist = all_dist(n, edges)
            total = sum(dist[i][perm[i]-1] for i in range(n))
            best, bestp = brute_min(n, edges)
            if total != ans or total != best:
                print("Mismatch for n=", n, "edges=", edges)
                print("brute best=", best, "bestp=", bestp)
                print("prog ans=", ans, "perm=", perm, "sum=", total)
                failures.append((n, edges, proc.stdout, proc.stderr))
    if not failures:
        print("All tests passed.")
    else:
        print(len(failures), "failures")

if __name__ == "__main__":
    main()
