#!/usr/bin/env python3
from typing import List

# AHU-style rooted-tree encoding utilities

def ahu_encoding(adj: List[List[int]], root: int) -> str:
    def dfs(u: int, p: int) -> str:
        codes = []
        for v in adj[u]:
            if v == p:
                continue
            codes.append(dfs(v, u))
        codes.sort()
        return "(" + "".join(codes) + ")"
    return dfs(root, -1)


def colorfulness(adj: List[List[int]]) -> int:
    n = len(adj)
    encs = [ahu_encoding(adj, r) for r in range(n)]
    return len(set(encs))
