#!/usr/bin/env python3
import sys
from typing import List

# Phase 1: baseline utilities (AHU encoding)

def ahu_encoding(adj: List[List[int]], root: int) -> str:
    def dfs(u: int, p: int) -> str:
        codes = []
        for v in adj[u]:
            if v == p:
                continue
            codes.append(dfs(v, u))
        codes.sort()
        return "(" + "".join(codes) + ")"
    return dfs(root, -1)


def colorfulness(adj: List[List[int]]) -> int:
    n = len(adj)
    encs = [ahu_encoding(adj, r) for r in range(n)]
    return len(set(encs))


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("0 0")
        return
    it = iter(data)
    n = int(next(it))
    adj = [[] for _ in range(n)]
    for _ in range(n - 1):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        adj[a].append(b)
        adj[b].append(a)

    cf = colorfulness(adj)
    leaves = sum(1 for i in range(n) if len(adj[i]) == 1)
    print(cf, leaves)

if __name__ == "__main__":
    main()
