using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if(!(cin >> n >> m)) return 0;
    vector<string> g(n);
    for(int i = 0; i < n; ++i) cin >> g[i];

    // Convert to 0/1 grid: 1 for '*', 0 for '.'
    vector<vector<int>> a(n, vector<int>(m, 0));
    for(int i = 0; i < n; ++i)
        for(int j = 0; j < m; ++j)
            a[i][j] = (g[i][j] == '*');

    // 2D prefix sums for fast region sums
    vector<vector<int>> ps(n+1, vector<int>(m+1, 0));
    for(int i = 0; i < n; ++i)
        for(int j = 0; j < m; ++j)
            ps[i+1][j+1] = a[i][j] + ps[i][j+1] + ps[i+1][j] - ps[i][j];

    auto sumRect = [&](int r, int c, int sz){
        int r2 = r + sz, c2 = c + sz;
        return ps[r2][c2] - ps[r][c2] - ps[r2][c] + ps[r][c];
    };

    int minNM = min(n, m);
    int maxT = 0; // floor(log2(minNM))
    while((1 << (maxT + 1)) <= minNM) ++maxT;
    if(maxT < 2){ cout << 0 << "\n"; return 0; }

    // dp[t] -> flattened 2D grid of size (n - 2^t + 1) x (m - 2^t + 1), each entry is a uint16_t mask of M in [0..15]
    vector<vector<uint16_t>> dp(maxT + 1);

    // t = 1: size 2x2 blocks
    int s1 = 2; int H1 = n - s1 + 1; int W1 = m - s1 + 1;
    dp[1].assign(H1 * W1, 0);
    for(int i = 0; i < H1; ++i){
        for(int j = 0; j < W1; ++j){
            int M = (a[i][j]     ? 1 : 0)
                  | (a[i][j+1]   ? 2 : 0)
                  | (a[i+1][j]   ? 4 : 0)
                  | (a[i+1][j+1] ? 8 : 0);
            dp[1][i * W1 + j] = uint16_t(1) << M;
        }
    }

    // t >= 2
    for(int t = 2; t <= maxT; ++t){
        int sz = 1 << t; int half = sz >> 1; // quadrant size
        int H = n - sz + 1; int W = m - sz + 1;
        if(H <= 0 || W <= 0) { dp[t].clear(); continue; }
        dp[t].assign(H * W, 0);
        int WPrev = m - half + 1; // width for t-1 level
        for(int i = 0; i < H; ++i){
            for(int j = 0; j < W; ++j){
                uint16_t bits = 0;
                for(int M = 0; M < 16; ++M){
                    bool ok = true;
                    // quadrants: 0=TL, 1=TR, 2=BL, 3=BR
                    for(int k = 0; k < 4 && ok; ++k){
                        int bit = (M >> k) & 1;
                        int r = (k == 0 || k == 1) ? i : i + half;
                        int c = (k == 0 || k == 2) ? j : j + half;
                        if(bit){
                            int sum = sumRect(r, c, half);
                            if(sum != half * half) ok = false;
                        } else {
                            int idxPrev = r * WPrev + c; // top-left of quadrant in size half
                            if( (dp[t-1][idxPrev] & (uint16_t(1) << M)) == 0) ok = false;
                        }
                    }
                    if(ok) bits |= (uint16_t(1) << M);
                }
                dp[t][i * W + j] = bits;
            }
        }
    }

    long long ans = 0;
    for(int t = 2; t <= maxT; ++t){
        int sz = 1 << t; int H = n - sz + 1; int W = m - sz + 1;
        if(H <= 0 || W <= 0) continue;
        for(int p = 0; p < H * W; ++p){ if(dp[t][p]) ++ans; }
    }

    cout << ans << "\n";
    return 0;
}
