#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; if(!(cin>>n)) return 0;
    vector<vector<pair<int,int>>> adj(n+1);
    for(int i=1;i<=n-1;i++){
        int a,b; cin>>a>>b;
        adj[a].push_back({b,i});
        adj[b].push_back({a,i});
    }

    int Delta = 0; for(int i=1;i<=n;i++) Delta = max(Delta, (int)adj[i].size());

    vector<int> in_color(n+1,0), edge_color(n,0);
    vector<pair<int,int>> st; st.reserve(n);
    st.push_back({1,0}); in_color[1] = 0;
