        int c = 1;
        for(auto &e: adj[u_node]){
            int v_node = e.first; int id = e.second; if(v_node==p) continue;
            if(c == in_color[u_node]) ++c;
            edge_color[id] = c; in_color[v_node] = c; ++c;
            st.push_back({v_node, u_node});
        }
    }

    vector<vector<int>> day(Delta+1);
    for(int i=1;i<=n-1;i++) day[edge_color[i]].push_back(i);

