        if(a.pri != b.pri) return a.pri > b.pri; // min-heap by pri
        return a.v > b.v;
    }};
    priority_queue<Node, vector<Node>, Cmp> pq; // leaves heap (priority, vertex)

    auto push_leaf = [&](int v){
        if(v < 1 || v > n) return;
        if(alive[v] && deg[v] <= 1 && burn[v] == 0){
            pq.push({p[v], v});
        }
    };

    // initialize leaves
