    auto remaining_last = [&]() -> int {
        int last = -1;
        for(int i = 1; i <= n; ++i) if(alive[i]) { last = i; break; }
        return last;
    };

    auto burn_next = [&](int target)->void{
        // burn leaves until target burns or all burnt
        while(burn[target] == 0 && alive_cnt > 1){
            if(pq.empty()) break;
            auto cur = pq.top(); pq.pop();
            int v = cur.v;
            if(!alive[v] || deg[v] != 1) continue; // not a leaf anymore
            if(burn[v] != 0) continue;
            if(cur.pri != p[v]){ // outdated priority, reinsert with current
