vector<int> parent_, depth_, heavy, head, pos, sz;
int curPos = 0;

int dfs(int v, int p){
    parent_[v] = p; sz[v] = 1; int maxsz = 0; heavy[v] = -1;
    for(int u : adj[v]) if(u != p){
        depth_[u] = depth_[v] + 1;
        int s = dfs(u, v);
        sz[v] += s;
        if(s > maxsz){ maxsz = s; heavy[v] = u; }
    }
    return sz[v];
}

void decompose(int v, int h){
    head[v] = h; pos[v] = ++curPos;
    if(heavy[v] != -1) decompose(heavy[v], h);
    for(int u : adj[v]) if(u != parent_[v] && u != heavy[v]) decompose(u, u);
}

int lca(int a, int b){
    while(head[a] != head[b]){
        if(depth_[head[a]] > depth_[head[b]]) a = parent_[head[a]]; else b = parent_[head[b]];
    }
    return depth_[a] < depth_[b] ? a : b;
}

int distNodes(int a, int b){ int c = lca(a,b); return depth_[a] + depth_[b] - 2*depth_[c]; }

long long queryPath(int u, int v, Fenwick &bit){
    long long res = 0;
    while(head[u] != head[v]){
        if(depth_[head[u]] < depth_[head[v]]) swap(u, v);
        int hu = head[u];
        res += bit.rangeSum(pos[hu], pos[u]);
        u = parent_[hu];
    }
    if(depth_[u] < depth_[v]) swap(u, v);
    res += bit.rangeSum(pos[v], pos[u]);
    return res;
}

