    int t = x;
    for(int p : primes){ if(1LL*p*p > t) break; if(t % p == 0){ int cnt = 0; while(t % p == 0){ t/=p; cnt++; } res.push_back({p,cnt}); } }
    }
    if(t > 1) res.push_back({t,1});
    return res;
}

