        vector<NodeInfo> nodesVec;
        if(auto it = nodesForPrime.find(p); it != nodesForPrime.end()){
            nodesVec.reserve(it->second.size());
            for(auto &nb : it->second) nodesVec.push_back({nb.first, nb.second});
            sort(nodesVec.begin(), nodesVec.end(), [](const NodeInfo &a, const NodeInfo &b){ return a.b < b.b; });
        }
        // sort queries by exponent e
        sort(qlist.begin(), qlist.end(), [](const QueryEntry &a, const QueryEntry &b){ if(a.e != b.e) return a.e < b.e; return a.qid < b.qid; });
