#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

struct Fenwick {
    int n; 
    vector<long long> f;
    Fenwick(int n=0){ init(n); }
    void init(int n_) { n = n_; f.assign(n+1, 0); }
    void add(int i, long long delta){ for(int x=i; x<=n; x += x & -x) f[x] += delta; }
    long long sumPrefix(int i){ long long s=0; for(int x=i; x>0; x -= x & -x) s += f[x]; return s; }
    long long rangeSum(int l, int r){ if(l>r) return 0; return sumPrefix(r) - sumPrefix(l-1); }
};

int n;
vector<vector<int>> adj;
vector<int> parent_, depth_, heavy, head, pos, sz;
int curPos = 0;

int dfs(int v, int p){
    parent_[v] = p; sz[v] = 1; int maxsz = 0; heavy[v] = -1;
    for(int u : adj[v]) if(u != p){
        depth_[u] = depth_[v] + 1;
        int s = dfs(u, v);
        sz[v] += s;
        if(s > maxsz){ maxsz = s; heavy[v] = u; }
    }
    return sz[v];
}

void decompose(int v, int h){
    head[v] = h; pos[v] = ++curPos;
    if(heavy[v] != -1) decompose(heavy[v], h);
    for(int u : adj[v]) if(u != parent_[v] && u != heavy[v]) decompose(u, u);
}

int lca(int a,int b){
    while(head[a] != head[b]){
        if(depth_[head[a]] > depth_[head[b]]) a = parent_[head[a]]; else b = parent_[head[b]];
    }
    return depth_[a] < depth_[b] ? a : b;
}

int distNodes(int a,int b){ int c = lca(a,b); return depth_[a] + depth_[b] - 2*depth_[c]; }

long long queryPath(int u,int v, Fenwick &bit){
    long long res=0;
    while(head[u] != head[v]){
        if(depth_[head[u]] < depth_[head[v]]) swap(u,v);
        int hu = head[u];
        res += bit.rangeSum(pos[hu], pos[u]);
        u = parent_[hu];
    }
    if(depth_[u] < depth_[v]) swap(u,v);
    res += bit.rangeSum(pos[v], pos[u]);
    return res;
}

vector<int> primes;
void sieve(int limit){
    vector<char> is(limit+1, true);
    if(limit >= 0){ is[0] = false; if(limit >= 1) is[1] = false; }
    for(int i=2; i*i<=limit; ++i) if(is[i]) for(int j=i*i; j<=limit; j+=i) is[j] = false;
    for(int i=2; i<=limit; ++i) if(is[i]) primes.push_back(i);
}

vector<pair<int,int>> factorizeInt(int x){
    vector<pair<int,int>> res;
    int t = x;
    for(int p : primes){
        if(1LL*p*p > t) break; 
        if(t % p == 0){ int cnt = 0; while(t % p == 0){ t/=p; cnt++; } res.push_back({p,cnt}); }
    }
    if(t > 1) res.push_back({t,1});
    return res;
}
long long modPow(long long a, long long e){
    long long res = 1 % MOD; a %= MOD; 
    while(e > 0){ if(e & 1) res = (res * a) % MOD; a = (a * a) % MOD; e >>= 1; }
    return res;
}

