    for(int i=0;i<q;i++){
        int u,v,x; cin >> u >> v >> x; U[i]=u; V[i]=v; auto fx = factorizeInt(x); for(auto &pe : fx){ queriesForPrime[pe.first].push_back({i, pe.second, u, v}); }
    }

    // Build HLD
    vector<int> parent(n+1,0), depth(n+1,0), heavyv(n+1,-1), headv(n+1,0), posv(n+1,0), szv(n+1,0);
    function<int(int,int)> dfs2 = [&](int v,int p){ parent[v] = p; szv[v] = 1; int maxsz=0; heavyv[v] = -1; for(int to: adj[v]) if(to != p){ depth[to] = depth[v] + 1; int s = dfs2(to,v); szv[v] += s; if(s > maxsz){ maxsz = s; heavyv[v] = to; } } return szv[v]; };
    function<void(int,int)> decomp2 = [&](int v,int h){ headv[v] = h; posv[v] = ++curPos; if(heavyv[v] != -1) decomp2(heavyv[v], h); for(int to: adj[v]) if(to != parent[v] && to != heavyv[v]) decomp2(to, to); };
