        vector<int> t(n+1, 0);
        auto it = nodesForPrime.find(p);
        vector<pair<int,int>> nodes; nodes.reserve(it==nodesForPrime.end()?0:it->second.size());
        if(it != nodesForPrime.end()){
            for(auto &nb : it->second){ t[nb.first] = nb.second; nodes.push_back({nb.first, nb.second}); }
        }
        // Build total path sums for this prime
        Fenwick bitTotal(n); for(int i=1;i<=n;i++) bitTotal.add(posv[i], t[i]);
        // Prepare activation list (nodes with t>0), sorted by t ascending
        sort(nodes.begin(), nodes.end(), [](const pair<int,int>&a, const pair<int,int>&b){ if(a.second != b.second) return a.second < b.second; return a.first < b.first; });
        // Sort queries by exponent e ascending
        sort(qlist.begin(), qlist.end(), [](const QueryEntry &a, const QueryEntry &b){ if(a.e != b.e) return a.e < b.e; return a.qid < b.qid; });
        Fenwick bitCount(n), bitSum(n);
        size_t idx = 0;
        for(auto &qe : qlist){ int e = qe.e; while(idx < nodes.size() && nodes[idx].second <= e){ int node = nodes[idx].first; int val = nodes[idx].second; bitCount.add(posv[node], 1); bitSum.add(posv[node], val); idx++; }
            long long C1 = queryPath(qe.u, qe.v, bitCount);
            long long S1 = queryPath(qe.u, qe.v, bitSum);
            int L = distNodes(qe.u, qe.v) + 1;
            long long exp = S1 + 1LL * e * (L - C1);
            if(exp) ans[qe.qid] = (ans[qe.qid] * modPow(p, exp)) % MOD;
        }
    }

    for(int i=0;i<q;i++){
        cout << ( (ans[i] % MOD + MOD) % MOD ) << "\n";
    }
    return 0;
}
