def brute_case(N, edges):
    g = [[] for _ in range(N)]
    for a, b in edges:
        a -= 1; b -= 1
        g[a].append(b)
        g[b].append(a)
    from functools import lru_cache
    res = []
    for k in range(N):
        start_mask = 1 << k
        frontier = set()
        for nb in g[k]:
            frontier.add(nb)
        @lru_cache(None)
        def dfs(assigned_mask, frontier_frozenset):
            if assigned_mask == (1 << N) - 1:
                return 1
            frontier_set = set(frontier_frozenset)
            total = 0
