            int u,v; cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        // Precompute depth from node 1 for tie-breaking
        vector<int> depth(n+1, -1);
        queue<int> q0;
        depth[1] = 0; q0.push(1);
        while(!q0.empty()) {
            int u = q0.front(); q0.pop();
            for (int w : adj[u]) if (depth[w] == -1) {
                depth[w] = depth[u] + 1;
                q0.push(w);
            }
        }

        auto reachable_within_k = [&](int start, int target, int k) {
            // BFS from start up to distance k, check if target reachable
            vector<int> dist(n+1, -1);
            queue<int> q; dist[start] = 0; q.push(start);
            while(!q.empty()) {
                int u = q.front(); q.pop();
                if (u == target) return true;
                if (dist[u] == k) continue;
                for (int w : adj[u]) if (dist[w] == -1) {
                    dist[w] = dist[u] + 1;
                    q.push(w);
                }
            }
            return false;
