            eaten[1] = true; // start at 1 and eat it
            int eaten_cnt = 1;
            int cur = 1;
            // We'll perform up to n-1 moves
            while (eaten_cnt < n) {
                // BFS from cur to find nearest uneaten node within distance <= k
                vector<int> dist(n+1, -1);
                queue<int> q;
                dist[cur] = 0; q.push(cur);
                int bestNode = -1; int bestDist = INT_MAX; // distance to candidate
                while(!q.empty()) {
