                    if (dist[u] > k) continue; // beyond smell range
                    if (!eaten[u] && dist[u] < bestDist) {
                        bestDist = dist[u];
                        bestNode = u;
                    } else if (!eaten[u] && dist[u] == bestDist) {
                        // tie-break by depth from node 1 (prefer deeper)
                        if (bestNode == -1 || depth[u] > depth[bestNode]) bestNode = u;
