    for (ull v : B) ((v >> bit) & 1ULL) ? B1.push_back(v) : B0.push_back(v);
    ull kb = (K >> bit) & 1ULL;
    ull Kp = K & ((1ULL << bit) - 1ULL);
    if (kb == 0) {
        return countCross(A0, B0, bit - 1, Kp) + countCross(A1, B1, bit - 1, Kp);
    } else {
        ull res = (ull)A0.size() * (ull)B0.size() + (ull)A1.size() * (ull)B1.size();
        res += countCross(A0, B1, bit - 1, Kp) + countCross(A1, B0, bit - 1, Kp);
        return res;
    }
}

