        double delta = (X[j] + 1 <= n) ? tails[j][X[j] + 1] : 0.0;
        pq.push({delta, j});
    }
    for (int step = 0; step < n; ++step) {
        auto cur = pq.top(); pq.pop();
        int j = cur.j;
        X[j] += 1;
        double delta = (X[j] + 1 <= n) ? tails[j][X[j] + 1] : 0.0;
        pq.push({delta, j});
    }

    long double E = 0.0L;
    for (int j = 0; j < m; ++j) {
        int x = X[j]; if (x < 0) x = 0; if (x > n) x = n;
        E += (long double)pref[j][x];
    }

    cout.setf(std::ios::fixed);
    cout << setprecision(12) << (double)E << "\n";
    return 0;
