    for (int i = 0; i < n1; ++i) fa[i] = A[i];
    for (int i = 0; i < n2; ++i) fb[i] = B[i];
    fft(fa, false); fft(fb, false);
    for (int i = 0; i < n; ++i) fa[i] *= fb[i];
