// Ordered set for 1..n values (distinct) per BIT node
typedef tree<int, null_type, less<int>, rb_tree_tag, tree_order_statistics_node_update> ordered_set;

// Global structures for Cartesian tree on W[1..n-1]

struct Node {
    int left = -1, right = -1; // child ids
    int L, M, R; // leaf index range: L..M left, M+1..R right
    int leaf_pos; // for leaves: position i
