// Segment tree to query index of minimum in W-range [l..r]
struct MinSeg {
    int n;
    vector<int> st; // stores index of min value in W
    MinSeg(int n=0): n(n) { st.assign(4*max(1,n), -1); }
    void build(const vector<int>& arr, int p, int l, int r){
        if(l==r){ st[p] = l; return; }
        int m=(l+r)>>1; build(arr,p<<1,l,m); build(arr,p<<1|1,m+1,r);
        int li = st[p<<1], ri = st[p<<1|1];
        st[p] = (arr[li] < arr[ri] ? li : ri);
    }
    void init(const vector<int>& arr){ // arr indexed 1..n-1
        if((int)arr.size()<=0) return;
        n = (int)arr.size()-1; st.assign(4*max(1,n), -1); build(arr,1,1,n);
    }
