struct Hull {
    vector<Line> lines;
    vector<long double> pos; // intersection X where line i becomes better than i-1
    int ptr = 0;
    long double intersectX(const Line& l1, const Line& l2) const { return (l2.b - l1.b) / (l1.m - l2.m); }
    void clear(){ lines.clear(); pos.clear(); ptr = 0; }
    void addLine(long double m, long double b){
        Line L{m,b};
