            else break;
        }
        lines.push_back(L);
        if(lines.size() == 1) pos.push_back(NEG_INF);
        else {
            long double x = intersectX(lines[lines.size()-2], lines[lines.size()-1]);
            pos.push_back(x);
        }
    }
    long double query(long double x){
        if(lines.empty()) return INF;
        if(ptr >= (int)lines.size()) ptr = (int)lines.size()-1;
        while(ptr+1 < (int)lines.size() && pos[ptr+1] <= x) ++ptr;
        return lines[ptr].val(x);
    }
