        Matrix N(m, vector<long long>(m, 0));
        for(int k = 0; k < m; ++k){
            auto nk_add = nextState(k, c);
            if(nk_add.second){
                int nk = nk_add.first;
                N[nk][k] = (N[nk][k] + 1) % MOD;
            }
        }
        return tuple<Matrix,Matrix,Matrix>(A, B, N);
