        Nv[i] = matAdd(t1, t2);
    }

    Matrix &NN = Nv[x];
    long long ans = 0;
    for(int i = 0; i < m; ++i){
        ans += NN[i][0];
        if(ans >= MOD) ans -= MOD;
    }
    cout << (ans % MOD) << '\n';
    return 0;
}
