#include <bits/stdc++.h>
using namespace std;

struct Edge { int to; long long cap; int rev; };

struct Dinic {
    int N; vector<vector<Edge>> G; vector<int> level, it;
    Dinic(int n=0){ init(n); }
    void init(int n){ N = n; G.assign(n, {}); level.resize(n); it.resize(n); }
    void add_edge(int u, int v, long long cap){ Edge a{v, cap, (int)G[v].size()}; Edge b{u, 0, (int)G[u].size()}; G[u].push_back(a); G[v].push_back(b); }
    bool bfs(int s, int t){ fill(level.begin(), level.end(), -1); queue<int> q; level[s] = 0; q.push(s); while(!q.empty()){ int v = q.front(); q.pop(); for(const auto &e: G[v]) if(e.cap > 0 && level[e.to] == -1){ level[e.to] = level[v] + 1; q.push(e.to); } } return level[t] != -1; }
    long long dfs(int v, int t, long long f){ if(v == t) return f; for(int &i = it[v]; i < (int)G[v].size(); ++i){ Edge &e = G[v][i]; if(e.cap > 0 && level[e.to] == level[v] + 1){ long long ret = dfs(e.to, t, min(f, e.cap)); if(ret > 0){ e.cap -= ret; G[e.to][e.rev].cap += ret; return ret; } } } return 0; }
    long long max_flow(int s, int t){ long long flow = 0; const long long INF = (1LL<<60); while(bfs(s,t)){ fill(it.begin(), it.end(), 0); while(true){ long long f = dfs(s,t,INF); if(!f) break; flow += f; } } return flow; }
};

int main(){ ios::sync_with_stdio(false); cin.tie(nullptr);
    int w, l; if(!(cin >> w >> l)) return 0; int n = w - 1; vector<long long> a(n+1, 0);
