    const long long INF = (1LL<<60) / 4;
    int S = 0;
    int in_base = 1; // i_in: 1..n
    int out_base = in_base + n; // i_out: n+1 .. 2n
    int T = out_base + n; // sink
    int N_est = 5 * max(1, n) + 10; // upper bound for node count
    Dinic din(N_est);
    auto in_node = [&](int i){ return in_base + (i - 1); };
    auto out_node = [&](int i){ return out_base + (i - 1); };

    // S -> i_in for initial jumps
