using namespace std;

struct Edge { int to; long long cap; int rev; };

struct Dinic {
    int N; vector<vector<Edge>> G; vector<int> level, it;
    Dinic(int n=0){ init(n); }
    void init(int n){ N = n; G.assign(n, {}); level.resize(n); it.resize(n); }
    void add_edge(int u, int v, long long cap){ Edge a{v, cap, (int)G[v].size()}; Edge b{u, 0, (int)G[u].size()}; G[u].push_back(a); G[v].push_back(b); }
    bool bfs(int s, int t){ fill(level.begin(), level.end(), -1); queue<int> q; level[s] = 0; q.push(s); while(!q.empty()){ int v = q.front(); q.pop(); for(const auto &e: G[v]) if(e.cap > 0 && level[e.to] == -1){ level[e.to] = level[v] + 1; q.push(e.to); } } return level[t] != -1; }
    long long dfs(int v, int t, long long f){ if(v == t) return f; for(int &i = it[v]; i < (int)G[v].size(); ++i){ Edge &e = G[v][i]; if(e.cap > 0 && level[e.to] == level[v] + 1){ long long ret = dfs(e.to, t, min(f, e.cap)); if(ret > 0){ e.cap -= ret; G[e.to][e.rev].cap += ret; return ret; } } } return 0; }
    long long max_flow(int s, int t){ long long flow = 0; const long long INF = (1LL<<60); while(bfs(s,t)){ fill(it.begin(), it.end(), 0); while(true){ long long f = dfs(s,t,INF); if(!f) break; flow += f; } } return flow; }
};

int main(){ ios::sync_with_stdio(false); cin.tie(nullptr);
    int w, l; if(!(cin >> w >> l)) return 0; int n = w - 1; vector<long long> a(n+1, 0);
    for(int i = 1; i <= n; ++i) cin >> a[i];
    const long long INF = (1LL<<60) / 4;
    int S = 0;
    int in_base = 1; // i_in: 1..n
    int out_base = in_base + n; // i_out: n+1 .. 2n
    int T = out_base + n; // sink index
    int N_est = 5 * max(1, n) + 100; // rough upper bound for nodes
    Dinic din(N_est);
    auto in_node = [&](int i){ return in_base + (i - 1); };
    auto out_node = [&](int i){ return out_base + (i - 1); };

    int upto = min(l, n);
    for(int i = 1; i <= upto; ++i) din.add_edge(S, in_node(i), INF);
    for(int i = 1; i <= n; ++i) if(a[i] > 0) din.add_edge(in_node(i), out_node(i), a[i]);
    for(int i = 1; i <= n; ++i) if(w - i <= l) din.add_edge(out_node(i), T, INF);

    struct SegNode { int graph_id; int l, r; int left_idx, right_idx; };
    vector<SegNode> seg; vector<int> leaf_to_idx(n+1, -1);
    int next_graph_id = T + 1;

    function<int(int,int)> build = [&](int L, int R)->int{
        int graph_id = next_graph_id++;
        int idx = (int)seg.size(); seg.push_back({graph_id, L, R, -1, -1});
        if(L == R){ leaf_to_idx[L] = idx; din.add_edge(graph_id, in_node(L), INF); }
        else {
            int M = (L + R) / 2;
            int li = build(L, M); int ri = build(M+1, R);
            seg[idx].left_idx = li; seg[idx].right_idx = ri;
            din.add_edge(graph_id, seg[li].graph_id, INF);
            din.add_edge(graph_id, seg[ri].graph_id, INF);
        }
        return idx;
    };
    function<void(int,int,int,vector<int>&)> collect = [&](int idx, int ql, int qr, vector<int>& res){ SegNode &nd = seg[idx]; if(qr < nd.l || nd.r < ql) return; if(ql <= nd.l && nd.r <= qr){ res.push_back(nd.graph_id); return; } if(nd.left_idx != -1) collect(nd.left_idx, ql, qr, res); if(nd.right_idx != -1) collect(nd.right_idx, ql, qr, res); };
    if(n > 0){ int root = build(1, n); for(int i = 1; i <= n; ++i){ int L = i + 1; int R = min(i + l, n); if(L <= R){ vector<int> ids; collect(0, L, R, ids); for(int gid : ids){ din.add_edge(out_node(i), gid, INF); } } } }
    }

    long long ans = din.max_flow(S, T);
    cout << ans << "\n";
    return 0;
}
