  long long INF = (long long)4e18; // large enough infinity
  int S = 0;
  int in_base = 1;            // i_in: 1..n
  int out_base = in_base + n;  // i_out: n+1 .. 2n
  int T = out_base + n;        // sink index

  int max_nodes = 1 + 2*n + 1 + 4*n; // S + in + out + T + seg-tree nodes (~4n)
  Dinic din(max_nodes + 5);

  auto in_node = [&](int i){ return in_base + (i - 1); };
  auto out_node = [&](int i){ return out_base + (i - 1); };

  // S -> i_in for initial jumps (i <= l)
  int upto = min(l, n);
  for(int i = 1; i <= upto; ++i) din.add_edge(S, in_node(i), INF);

  // i_in -> i_out with capacity a[i]
  for(int i = 1; i <= n; ++i) if(a[i] > 0) din.add_edge(in_node(i), out_node(i), a[i]);

  // i_out -> T if can finish from i (w - i <= l)
  for(int i = 1; i <= n; ++i) if(w - i <= l) din.add_edge(out_node(i), T, INF);

  // Build segment tree over [1..n]
  struct SegNode { int l, r; int graph_id; int left, right; };
  vector<SegNode> seg;
  int nextGraph = T + 1; // graph IDs for seg-tree nodes

  function<int(int,int)> build = [&](int L, int R)->int{
    int idx = (int)seg.size();
    seg.push_back({L, R, nextGraph, -1, -1});
    int gid = nextGraph++;
    seg[idx].graph_id = gid;
    if(L == R){
      din.add_edge(gid, in_node(L), INF);
    } else {
      int M = (L + R) / 2;
      int li = build(L, M); int ri = build(M+1, R);
      seg[idx].left = li; seg[idx].right = ri;
      din.add_edge(gid, seg[li].graph_id, INF);
      din.add_edge(gid, seg[ri].graph_id, INF);
    }
    return idx;
  };

  function<void(int,int,int,vector<int>&)> addRange = [&](int idx, int ql, int qr, vector<int>& out){
    int L = seg[idx].l, R = seg[idx].r;
    if(qr < L || R < ql) return;
    if(ql <= L && R <= qr){ out.push_back(seg[idx].graph_id); return; }
    if(seg[idx].left != -1) addRange(seg[idx].left, ql, qr, out);
    if(seg[idx].right != -1) addRange(seg[idx].right, ql, qr, out);
  };

  if(n > 0){ int root = build(1, n); for(int i = 1; i <= n; ++i){ int L = i + 1; int R = min(i + l, n); if(L <= R){ vector<int> gids; addRange(root, L, R, gids); for(int gid : gids){ din.add_edge(out_node(i), gid, INF); } } } }
  }

  long long ans = din.max_flow(S, T);
  cout << ans << "\n";
  return 0;
}
