    vector<int> U(n-1), V(n-1);            // endpoints of edges (directed from U[i] -> V[i])
    vector<int> dir(n-1, 0);               // 0 means U[i] -> V[i], 1 means V[i] -> U[i]
    vector<vector<pair<int,int>>> adj(n);

