                bool inB_v = (db_v < da_v);
                if(inB_u && inB_v){
                    if(db_u < db_v){ if(!edgeFrom(ei, u, v)) badB0++; }
                    else { if(!edgeFrom(ei, v, u)) badB0++; }
                }
