                int da_u = dist[a][u], da_v = dist[a][v];
                int db_u = dist[b][u], db_v = dist[b][v];
                bool inA_u = (da_u < db_u);
                bool inA_v = (da_v < db_v);
                if(inA_u && inA_v){
                    if(da_u < da_v){ if(!edgeFrom(ei, u, v)) badA1++; }
