                if(inB_u && inB_v){
                    if(db_u < db_v){ if(!edgeFrom(ei, u, v)) badB1++; }
                    else { if(!edgeFrom(ei, v, u)) badB1++; }
                }
            }
            long long cost1 = badA1 + badB1;
            ans = min(ans, min(cost0, cost1));
        }
    }

    cout << ans << '\n';
    return 0;
