    for(int r = 0; r < n; ++r){
        for(int c = 0; c < m; ++c){
            if(grid[r][c] == '#') continue;
            int nr = r, nc = c;
            char ch = grid[r][c];
            if(ch == '^') nr = r - 1;
            else if(ch == 'v') nr = r + 1;
            else if(ch == '<') nc = c - 1;
            else if(ch == '>') nc = c + 1;
            // assume within bounds (border are '#')
            nxt[id(r,c)] = id(nr, nc);
        }
    }

    // Cycle detection among non-# cells
    vector<char> color(N, 0); // 0=unvisited,1=visiting,2=done
    for(int r = 0; r < n; ++r){
        for(int c = 0; c < m; ++c){
            if(grid[r][c] == '#') continue;
            int u = id(r,c);
            if(color[u] != 0) continue;
            vector<int> path;
            int cur = u;
            while(true){
                color[cur] = 1;
                path.push_back(cur);
                int v = nxt[cur];
                if(v == -1){
                    for(int w: path) color[w] = 2;
                    break;
                }
                int vr = v / m, vc = v % m;
                if(grid[vr][vc] == '#'){
                    // next is a sink; path ends here
                    for(int w: path) color[w] = 2;
                    break;
                }
                if(color[v] == 0){
                    cur = v;
                    continue;
                } else if(color[v] == 1){
                    cout << -1 << '\n';
                    return 0;
                } else {
                    for(int w: path) color[w] = 2;
                    break;
                }
            }
        }
    }

    // No cycles. Compute depths and sinks with iterative DP.
    vector<int> depth(N, -1);
    vector<int> sink(N, -1);
    vector<int> dmax(N, 0);           // per-sink maximum depth
    vector<char> usedSink(N, 0);      // whether a sink is used

    // Initialize sinks ( '#' cells )
    for(int r = 0; r < n; ++r){
        for(int c = 0; c < m; ++c){
            if(grid[r][c] == '#'){
                int u = id(r,c);
                depth[u] = 0;
                sink[u] = u;
                usedSink[u] = 1;
                dmax[u] = max(dmax[u], 0);
            }
        }
    }

    // For every non-# cell, compute depth and sink if not already computed
    for(int r = 0; r < n; ++r){
        for(int c = 0; c < m; ++c){
            if(grid[r][c] == '#') continue;
            int u = id(r,c);
            if(depth[u] != -1) continue;
            vector<int> st;
            int cur = u;
            // Traverse until we hit a known node (depth[cur] != -1) or a sink '#'
            while(grid[cur/m][cur%m] != '#'){
                if(depth[cur] != -1) break;
                st.push_back(cur);
                int v = nxt[cur];
                cur = v;
