            int baseDepth = depth[cur];
            int baseSink = sink[cur];
            // Unwind the stack
            while(!st.empty()){
                int vtx = st.back(); st.pop_back();
                baseDepth = baseDepth + 1;
                depth[vtx] = baseDepth;
                sink[vtx] = baseSink;
                if(depth[vtx] > dmax[baseSink]) dmax[baseSink] = depth[vtx];
                usedSink[baseSink] = 1;
            }
        }
    }

    // Count used sinks and find the first sink if needed
    int k = 0;
    int firstSink = -1;
    for(int r = 0; r < n; ++r){
        for(int c = 0; c < m; ++c){
            if(grid[r][c] == '#'){
                int u = id(r,c);
                if(usedSink[u]){ k++; if(firstSink==-1) firstSink = u; }
            }
        }
    }

    long long ans = 0;
    if(k >= 2){
        long long max1 = -1, max2 = -1;
        for(int r = 0; r < n; ++r){
            for(int c = 0; c < m; ++c){
                if(grid[r][c] == '#'){
                    int u = id(r,c);
                    if(!usedSink[u]) continue;
                    int d = dmax[u];
                    if(d > max1){ max2 = max1; max1 = d; }
                    else if(d > max2){ max2 = d; }
                }
            }
        }
        if(max2 >= 0) ans = max1 + max2;
        else ans = 0;
    } else {
        // Only one used sink. Compute two largest distinct depths among nodes with this sink.
        int s = firstSink;
        int max1 = -1, max2 = -1;
        for(int u = 0; u < N; ++u){
            if(sink[u] == s){
                int d = depth[u];
                if(d > max1){ max2 = max1; max1 = d; }
                else if(d != max1 && d > max2){ max2 = d; }
            }
        }
        if(max2 >= 0) ans = (long long)max1 + (long long)max2;
        else ans = 0;
    }

    cout << ans << '\n';
    return 0;
