    vector<int> topo; topo.reserve(K);
    while(!q.empty()){
        int u = q.front(); q.pop(); topo.push_back(u);
        for(int v : dag[u]) if(--indeg2[v] == 0) q.push(v);
    }

    // minReach[c][b] = min w·node over all nodes in components reachable from c (including c)
    vector<array<ll,8>> minReach(K);
