    for(int idx = (int)topo.size() - 1; idx >= 0; --idx){
        int u = topo[idx];
        for(int v : dag[u]){
            for(int b = 0; b < 8; ++b){
                if(minReach[v][b] < minReach[u][b]) minReach[u][b] = minReach[v][b];
            }
        }
    }

    // Compute answers for each node
    vector<ll> ans(N);
    for(int i = 0; i < N; ++i){
        int c = comp[i];
        ll best = 0;
        for(int b = 0; b < 8; ++b){
            ll wpt = (ll)sx[b]*x[i] + (ll)sy[b]*y[i] + (ll)sz[b]*z[i];
            ll cand = wpt - minReach[c][b];
            if(cand > best) best = cand;
        }
        ans[i] = best;
    }

    for(int i = 0; i < N; ++i) cout << ans[i] << "\n";
    return 0;
}
