#!/usr/bin/env python3
import sys
from collections import deque

def build_lca(adj, n, root=1):
    LOG = (n).bit_length()
    up = [[0]*(n+1) for _ in range(LOG)]
    depth = [0]*(n+1)
    stack = [(root, 0)]
    visited = [False]*(n+1)
    while stack:
        u, p = stack.pop()
        if visited[u]:
            continue
        visited[u] = True
        up[0][u] = p
        if p == 0:
            depth[u] = 0
        else:
            depth[u] = depth[p] + 1
        for v in adj[u]:
            if v == p:
                continue
            stack.append((v, u))
    for k in range(1, LOG):
        for v in range(1, n+1):
            mid = up[k-1][v]
            up[k][v] = up[k-1][mid] if mid else 0
    return up, depth

def lca(u, v, up, depth):
    if depth[u] < depth[v]:
        u, v = v, u
    diff = depth[u] - depth[v]
    k = 0
    while diff:
        if diff & 1:
            u = up[k][u]
        diff >>= 1
        k += 1
    if u == v:
        return u
    LOG = len(up)
    for k in range(LOG-1, -1, -1):
        if up[k][u] != up[k][v]:
            u = up[k][u]
            v = up[k][v]
    return up[0][u]

def dist(u, v, up, depth):
    w = lca(u, v, up, depth)
    return depth[u] + depth[v] - 2*depth[w]

def on_path(h, t, x, up, depth):
    return dist(h, x, up, depth) + dist(x, t, up, depth) == dist(h, t, up, depth)

def solve_case(n, a, b, edges):
    adj = [[] for _ in range(n+1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    up, depth = build_lca(adj, n, root=1)
    start = (a, b)
    target = (b, a)
    vis = set([start])
    dq = deque([start])
    while dq:
        h, t = dq.popleft()
        if (h, t) == target:
            return "YES"
        d = dist(h, t, up, depth)
        # Move head
        for nh in adj[h]:
            if not on_path(h, t, nh, up, depth):
                st = (nh, t)
                if st not in vis:
                    vis.add(st)
                    dq.append(st)
        # Move tail
        for nt in adj[t]:
            if not on_path(h, t, nt, up, depth):
                st = (h, nt)
                if st not in vis:
                    vis.add(st)
                    dq.append(st)
    return "NO"

def parse_input(data):
    it = iter(data.strip().split())
    t = int(next(it))
    res = []
    for _ in range(t):
        n = int(next(it)); a = int(next(it)); b = int(next(it))
        edges = []
        for i in range(n-1):
            u = int(next(it)); v = int(next(it))
            edges.append((u, v))
        res.append((n, a, b, edges))
    return res

def main():
    data = sys.stdin.read()
    tests = parse_input(data)
    out_lines = []
    for n, a, b, edges in tests:
        out_lines.append(solve_case(n, a, b, edges))
    print("\n".join(out_lines))

