using namespace std;

// Memory efficient tree representation and LCA with binary lifting
const int MAXN = 1000005; // 1e6 + margin
const int LOG = 20; // since 2^20 > 1e6

static int head[MAXN];
static int to[2*MAXN];
static int nxt[2*MAXN];
static int edge_cnt = 0;
static int depthArr[MAXN];
static int up[LOG][MAXN];
static bool isBlack[MAXN];
static int n, q;

static inline void add_edge(int u, int v) {
    to[edge_cnt] = v; nxt[edge_cnt] = head[u]; head[u] = edge_cnt++;
}

static int lca(int a, int b) {
    if (depthArr[a] < depthArr[b]) swap(a, b);
    int diff = depthArr[a] - depthArr[b];
    for (int k = 0; k < LOG; ++k) {
        if (diff & (1 << k)) a = up[k][a];
    }
    if (a == b) return a;
    for (int k = LOG - 1; k >= 0; --k) {
        if (up[k][a] != up[k][b]) {
            a = up[k][a];
            b = up[k][b];
        }
    }
    return up[0][a];
}
static inline int dist(int a, int b) {
    int c = lca(a, b);
    return depthArr[a] + depthArr[b] - 2 * depthArr[c];
}
static inline bool onPath(int a, int b, int c) { // is c on path a-b?
    int dab = dist(a, b);
    int dac = dist(a, c);
    int dcb = dist(c, b);
    return (dac + dcb == dab);
}

