    vector<char> vis(n + 1, 0);
    queue<int> qu;
    depthArr[root] = 0; up[0][root] = 0; vis[root] = 1; qu.push(root);
    while (!qu.empty()) {
        int u = qu.front(); qu.pop();
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (!vis[v]) {
                vis[v] = 1;
                depthArr[v] = depthArr[u] + 1;
                up[0][v] = u;
                qu.push(v);
            }
        }
    }
