#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 200000 + 5;
static const int LOG = 20;

int n;
vector<vector<int>> adj;
vector<array<int, LOG>> up;
vector<int> deptht;

void dfs(int v, int p){
    up[v][0] = p;
    for(int k = 1; k < LOG; ++k)
        up[v][k] = up[ up[v][k-1] ][k-1];
    for(int to : adj[v]) if(to != p){
        deptht[to] = deptht[v] + 1;
        dfs(to, v);
    }
}

int lca(int a, int b){
    if(deptht[a] < deptht[b]) swap(a,b);
    int diff = deptht[a] - deptht[b];
    for(int k = 0; k < LOG; ++k)
        if(diff & (1<<k)) a = up[a][k];
    if(a == b) return a;
    for(int k = LOG-1; k >= 0; --k){
        if(up[a][k] != up[b][k]){
            a = up[a][k];
            b = up[b][k];
        }
    }
    return up[a][0];
}

int dist(int a, int b){
    int c = lca(a,b);
    return deptht[a] + deptht[b] - 2*deptht[c];
}

bool on_path(int a, int b, int v){
    long long dab = dist(a,b);
    long long dav = dist(a,v);
    long long vdb = dist(v,b);
    return (dav + vdb == dab);
}

long long egcd(long long a, long long b, long long &x, long long &y){
    if(b == 0){ x = 1; y = 0; return a; }
    long long x1, y1;
    long long g = egcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

