    long long x, y;
    long long g = egcd(m1, m2, x, y);
    long long diff = a2 - a1;
    if(diff % g != 0) return false;
    long long lcm = m1 / g * m2; // safe in 64-bit given constraints
    long long m1_g = m1 / g;
    long long m2_g = m2 / g;
    long long diff_g = diff / g;
    long long inv, tmp;
    egcd(m1_g, m2_g, inv, tmp);
    inv %= m2_g; if(inv < 0) inv += m2_g;
    long long k = (diff_g % m2_g + m2_g) % m2_g;
    k = (k * inv) % m2_g;
    long long ans = a1 + m1 * k;
    ans %= lcm; if(ans < 0) ans += lcm;
    t = ans;
    return true;
}

