        add(a1); add(b1); add(a2); add(a3); add(a4); add(a5);
        sort(cand.begin(), cand.end()); cand.erase(unique(cand.begin(), cand.end()), cand.end());
        vector<int> inter;
        for(int c : cand){
            if(on_path(u,v,c) && on_path(x,y,c)) inter.push_back(c);
        }
