            long long negD2 = ((-D2) % m2 + m2) % m2;
            if(crt(D1, m1, negD2, m2, t0)){
                best = min(best, t0); found = true;
            }
        };
        try_endpoint(A);
        if(B != A) try_endpoint(B);
        if(!found){ cout << -1 << "\n"; }
        else { cout << best << "\n"; }
    }
    return 0;
}

