#include <bits/stdc++.h>
using namespace std;
static const long long MOD = 1000000007LL;

// Compute the number of colorings for a fixed order of children for all nodes.
// solveForOrder returns the total number of colorings for the subtree rooted at 1
// when children are processed in 'order' (for each node, order[v] lists its children in fixed order).
long long solveForOrder(int n, const vector<vector<int>>& order) {
    // dp[v][p][r] = number of colorings of subtree rooted at v,
    // where entering parity is p (0 or 1) and final global parity after finishing subtree is r (0 or 1).
    vector<array<array<long long,2>,2>> dp(n+1);

    function<void(int)> dfs = [&](int v){
        for(int u : order[v]) dfs(u);
        for(int a = 0; a < 2; ++a){
            long long dist[2] = {0, 0};
            dist[a ^ 1] = 1; // after painting v, parity toggles
            for(int u : order[v]){
                long long nd[2] = {0, 0};
                // option 1: do not paint this child
                nd[0] = (nd[0] + dist[0]) % MOD;
                nd[1] = (nd[1] + dist[1]) % MOD;
                // option 2: paint this child
                for(int t = 0; t < 2; ++t){
                    for(int r = 0; r < 2; ++r){
                        nd[r] = (nd[r] + dist[t] * dp[u][t][r]) % MOD;
                    }
                }
                dist[0] = nd[0];
                dist[1] = nd[1];
            }
            dp[v][a][0] = dist[0] % MOD;
            dp[v][a][1] = dist[1] % MOD;
        }
    };

    // root is 1; ensure the DFS starts from root
    dfs(1);
    long long ans = (dp[1][0][0] + dp[1][0][1]) % MOD;
    return ans;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin >> n)) return 0;
    vector<int> p(n+1, 0);
    for(int i = 2; i <= n; ++i) cin >> p[i];
    vector<vector<int>> children(n+1);
    for(int i = 2; i <= n; ++i) children[p[i]].push_back(i);

    // Build ascending and descending orders for every node
    vector<vector<int>> orderAsc(n+1), orderDesc(n+1);
    for(int v = 1; v <= n; ++v){
        orderAsc[v] = children[v];
        sort(orderAsc[v].begin(), orderAsc[v].end());
        orderDesc[v] = orderAsc[v];
        reverse(orderDesc[v].begin(), orderDesc[v].end());
    }

    long long asc = solveForOrder(n, orderAsc);
    long long desc = solveForOrder(n, orderDesc);

    // Note: The complete solution requires computing |A ∪ B|, the union of colorings
    // achievable with ascending and descending orders, without double counting.
    // For now, we output both per-order counts to verify the base mechanism.
    cout << asc << " " << desc << "\n";

    return 0;
}
