#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n; if(!(cin>>n)) return 0;
    vector<vector<int>> adj(n);
    for(int i=0;i<n-1;i++){
        int u,v; cin>>u>>v; --u; --v; adj[u].push_back(v); adj[v].push_back(u);
    }

    // Precompute all-pairs distances (tree -> BFS from each node)
    vector<vector<int>> dist(n, vector<int>(n, 0));
    for(int s=0;s<n;s++){
        vector<int> d(n, -1); queue<int> q; d[s] = 0; q.push(s);
        while(!q.empty()){
            int x = q.front(); q.pop();
            for(int y: adj[x]) if(d[y] == -1){ d[y] = d[x] + 1; q.push(y); }
        }
        for(int t=0;t<n;t++) dist[s][t] = d[t];
    }

    // ans[k] = maximum subset size for almost-k-uniform; k in [1..n], initialize to 1
    vector<int> ans(n+1, 1);
    int total = 1 << n;
    for(int mask = 1; mask < total; ++mask){
        int s = __builtin_popcount((unsigned)mask);
        if(s == 1) continue; // single vertex already covered by default 1
        int minD = INT_MAX, maxD = 0;
        vector<int> idx; idx.reserve(s);
        for(int i=0;i<n;i++) if(mask & (1<<i)) idx.push_back(i);
        bool prune = false;
        for(int i=0;i<(int)idx.size() && !prune; ++i){
            for(int j=i+1;j<(int)idx.size(); ++j){
                int a = idx[i], b = idx[j]; int d = dist[a][b];
                minD = min(minD, d); maxD = max(maxD, d);
                if(maxD - minD > 1){ prune = true; break; }
            }
        }
        if(!prune && maxD - minD <= 1){
            int k = minD;
            if(k >= 1 && k <= n) ans[k] = max(ans[k], s);
        }
    }

    for(int k=1;k<=n;k++) cout << ans[k] << (k==n ? '\n' : ' ');
    return 0;
}
