    vector< array<int, LOG> > up(n+1);
    for(int v=1; v<=n; ++v) for(int k=0;k<LOG;++k) up[v][k] = 0;
    for(int v=1; v<=n; ++v) up[v][0] = parent[v];
    for(int k=1; k<LOG; ++k){
        for(int v=1; v<=n; ++v){ int mid = up[v][k-1]; up[v][k] = (mid ? up[mid][k-1] : 0); }
    }

    auto lca = [&](int a, int b){
        if(depth[a] < depth[b]) swap(a,b);
        int diff = depth[a] - depth[b];
        for(int k=0;k<LOG;++k) if(diff & (1<<k)) a = up[a][k];
        if(a == b) return a;
        for(int k=LOG-1; k>=0; --k){
            if(up[a][k] != up[b][k]){ a = up[a][k]; b = up[b][k]; }
        }
        return up[a][0];
    };

    auto kth_ancestor = [&](int v, int k){
        for(int i=0; i<LOG && v; ++i) if(k & (1<<i)) v = up[v][i];
        return v;
    };

