            while(!q.empty()){
                auto [cy,cx] = q.front(); q.pop();
                for(auto &d: nb){ int ny = cy + d.first, nx = cx + d.second;
                    if(ny>=0 && ny<h2 && nx>=0 && nx<w2){ if(isBranch[ny][nx] && !seen[ny][nx]){ seen[ny][nx] = 1; q.push({ny,nx}); } }
                }
            }
        }}
        raysCounts.push_back(rays);
    }

    sort(raysCounts.begin(), raysCounts.end());
    cout << raysCounts.size() << "\n";
    for(size_t i=0; i<raysCounts.size(); ++i){ if(i) cout << " "; cout << raysCounts[i]; }
    cout << "\n";
    return 0;
}
