    const int dy[8] = {-1,-1,-1,0,0,1,1,1};
    const int dx[8] = {-1,0,1,-1,1,-1,0,1};

    auto at = [&](int y,int x)->int{ if(y<0||y>=H||x<0||x>=W) return 0; return img[y][x]; };

    bool changed = true;
    while(changed){
        changed = false;
        vector<pair<int,int>> del1;
        // Stage 1
        for(int y=1;y<H-1;y++){
            for(int x=1;x<W-1;x++){
                if(img[y][x]==1){
                    int B = 0; for(int k=0;k<8;k++) B += at(y+dy[k], x+dx[k]);
                    int A = 0;
                    int seq[8] = {
                        at(y-1,x), at(y-1,x+1), at(y,x+1), at(y+1,x+1),
                        at(y+1,x), at(y+1,x-1), at(y,x-1), at(y-1,x-1)
                    };
                    for(int i=0;i<8;i++) if(seq[i]==0 && seq[(i+1)%8]==1) A++;
                    if(B>=2 && B<=6 && A==1){
                        int p2 = at(y-1,x), p4 = at(y,x+1), p6 = at(y+1,x), p8 = at(y,x-1);
                        if(!(p2 && p4 && p6) && !(p4 && p6 && p8)){
                            del1.emplace_back(y,x);
                        }
                    }
                }
            }
        }
        if(!del1.empty()){
            for(auto &p: del1) img[p.first][p.second] = 0;
            changed = true;
        }
        // Stage 2
        vector<pair<int,int>> del2;
        for(int y=1;y<H-1;y++){
            for(int x=1;x<W-1;x++){
                if(img[y][x]==1){
                    int B = 0; for(int k=0;k<8;k++) B += at(y+dy[k], x+dx[k]);
                    int A = 0;
                    int seq[8] = {
                        at(y-1,x), at(y-1,x+1), at(y,x+1), at(y+1,x+1),
                        at(y+1,x), at(y+1,x-1), at(y,x-1), at(y-1,x-1)
                    };
                    for(int i=0;i<8;i++) if(seq[i]==0 && seq[(i+1)%8]==1) A++;
                    if(B>=2 && B<=6 && A==1){
