    for(int i=0;i<h;i++){
        for(int j=0;j<w;j++){ int v; cin>>v; grid[i][j] = v?1:0; }
    }

    // Find 8-connected components of 1s (sun regions)
    vector<vector<int>> comp(h, vector<int>(w,-1));
    vector<vector<pair<int,int>>> comps; comps.reserve(128);
    const int dy8[8] = {-1,-1,-1,0,0,1,1,1};
    const int dx8[8] = {-1,0,1,-1,1,-1,0,1};
    for(int y=0;y<h;y++){
        for(int x=0;x<w;x++){
            if(grid[y][x] && comp[y][x]==-1){
                int cid = (int)comps.size(); comps.emplace_back();
                queue<pair<int,int>> q; q.push({y,x}); comp[y][x]=cid;
                while(!q.empty()){
                    auto [cy,cx]=q.front(); q.pop(); comps.back().push_back({cy,cx});
                    for(int d=0; d<8; d++){
                        int ny=cy+dy8[d], nx=cx+dx8[d];
                        if(ny>=0 && ny<h && nx>=0 && nx<w && grid[ny][nx] && comp[ny][nx]==-1){ comp[ny][nx]=cid; q.push({ny,nx}); }
                    }
                }
            }
        }
    }

    vector<int> counts; counts.reserve(comps.size());
    for(auto &cells: comps){
        int minY = INT_MAX, maxY = INT_MIN, minX = INT_MAX, maxX = INT_MIN;
        for(auto &p: cells){ minY = min(minY, p.first); maxY = max(maxY, p.first); minX = min(minX, p.second); maxX = max(maxX, p.second); }
        int H2 = maxY - minY + 1; int W2 = maxX - minX + 1;
        if(H2 <= 2 || W2 <= 2){ counts.push_back(0); continue; }
        vector<vector<unsigned char>> local(H2, vector<unsigned char>(W2,0));
        for(auto &p: cells) local[p.first - minY][p.second - minX] = 1;

        thinning_ZhangSuen(local);
