        int endpoints = 0;
        for(int y=0; y<H2; y++){
            for(int x=0; x<W2; x++){
                if(local[y][x]==1){
                    int neigh = 0;
                    for(int dy=-1; dy<=1; dy++){
                        for(int dx=-1; dx<=1; dx++){
                            if(dy==0 && dx==0) continue;
                            int ny=y+dy, nx=x+dx;
                            if(ny>=0 && ny<H2 && nx>=0 && nx<W2 && local[ny][nx]) neigh++;
                        }
                    }
                    if(neigh == 1) endpoints++;
                }
            }
        }
        counts.push_back(endpoints);
    }

    sort(counts.begin(), counts.end());
    cout << counts.size() << "\n";
    for(size_t i=0;i<counts.size(); ++i){ if(i) cout << " "; cout << counts[i]; }
    cout << "\n";
    return 0;
}
